(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c49"]=[{"id":"00008434","register_sub_id":"101","register_pk":"134830","name":"坂田家住宅土蔵","kana":"さかたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県五泉市土堀字上ノ代295","lat":37.7332354,"lng":139.21817987,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0328","desc":"主屋の東南に少し離れて建つ。土蔵造二階建、桁行六・四メートル梁間四・〇メートル。置屋根の南北棟、切妻造桟瓦葺、西面全面にわたり下屋を設ける。外壁は腰を黒色とする漆喰仕上げ。内部は一尺ごと密に柱をたて竪板を張る。端正なつくりになる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008434"},{"id":"00008433","register_sub_id":"101","register_pk":"134829","name":"坂田家住宅古土蔵","kana":"さかたけじゅうたくふるどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市土堀字上ノ代295","lat":37.73324867,"lng":139.21790791,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0327","desc":"新蔵の東側に東西棟で建つ。土蔵造二階建、桁行六・一メートル梁間三・九メートル。置屋根の切妻造桟瓦葺で、北面に庇を設ける。外壁は漆喰仕上げで、腰と北面や開口の楣を黒漆喰を配する。内壁は二尺ごとに柱をたて、板壁。小規模ながら堅実なつくりの蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008433"},{"id":"00015426","register_sub_id":"101","register_pk":"533441","name":"笹口家住宅主屋","kana":"ささぐちけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市西蒲区松野尾字宮林3244他","lat":37.79701667,"lng":138.87134167,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積448㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0603","desc":"北国街道沿いに位置する酒造家の主屋。南面する東西棟の木造二階建、入母屋造桟瓦葺。各階は西側に座敷を二列並べ、オモテ、ナカ、ウラの廊下を通す。外観重厚で内部は上質な座敷を連ね、アールデコ調の洋間も備える。街道に面した大型で良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015426"},{"id":"00014345","register_sub_id":"101","register_pk":"511334","name":"習静菴（旧三星屋）土蔵","kana":"しゅうせいあん（きゅうみつぼしや）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県小千谷市大字時水字中ノ沢1410-1","lat":37.29618333,"lng":138.76686111,"geo_status":"db","era":"明治前期／平成19年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造二階建、鉄板葺、建築面積30㎡","structure_material":"木造二階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0568","desc":"市内千谷川の星野家にあった土蔵。切妻造平入の二階建の土蔵で、壁は鉢巻まで漆喰仕上、腰板張とし、妻面に窓を設ける。各階板敷だが、当初は一階を土間とした。中央に太い柱を立てて牛梁を支え、登梁形式とする。全体に材が太く、積雪に備えた雪国の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014345"},{"id":"00014344","register_sub_id":"101","register_pk":"511333","name":"習静菴茶室","kana":"しゅうせいあんちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県小千谷市大字時水字中ノ沢1410-1","lat":37.29624722,"lng":138.76690278,"geo_status":"db","era":"大正後期／平成13年・同19年移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0567","desc":"市内旧家にあった茶室で、切妻造銅板葺、平三畳向切茶室と四畳半待合を壁を挟んで並べ、廊下と躙り口側の土庇で繋ぐ。茶室は竹棹縁天井、手前座蒲天井、赤松の落とし掛け、櫟の中柱等とする。土庇と土間飛石は雁木を思わせる構成で、雪国の茶室に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014344"},{"id":"00009933","register_sub_id":"101","register_pk":"196080","name":"白田家住宅主屋","kana":"しらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県上越市頸城区森本703","lat":37.17547422,"lng":138.34644987,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積439㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0389","desc":"敷地中央に東面し、正面南寄りに入母屋造の玄関を張出す。主体部北寄りの床上部は居室を三列に配し、正側面に幅広の土縁を廻らせる。明治初期の大型民家の骨格を保ちつつ、ガラス建具の多用や座敷の造作などに大正期の洗練さが窺える、上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009933"},{"id":"00014781","register_sub_id":"101","register_pk":"519039","name":"杉原家住宅主屋","kana":"すぎはらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市上赤谷2631他","lat":37.83565556,"lng":139.41823889,"geo_status":"db","era":"明治32年／昭和30年改修、同35年増築、平成30年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積270㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0585","desc":"会津街道の赤谷宿に位置する旧家の主屋。桁行14間半の長大な木造2階建切妻造平入桟瓦葺の建物で、西面中央に入母屋造玄関を付す。北は土間、南は床上で広間や床構え付き座敷を配し、南辺に広縁を付す。広間の吹抜上部には豪壮な梁組を現した大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014781"},{"id":"00014782","register_sub_id":"101","register_pk":"519040","name":"杉原家住宅土蔵","kana":"すぎはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市上赤谷2631他","lat":37.83571944,"lng":139.41796667,"geo_status":"db","era":"明治18年／昭和4年増築、平成30年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡、地階付","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0586","desc":"主屋北西に位置する家財蔵。2階建切妻造平入地階付で、置屋根形式の桟瓦葺。東面に戸口を開けて下屋を付す。外壁は黒漆喰塗仕上、腰はモルタル塗仕上。一・二階板敷で中央に独立柱を立て、地階は土間。妻に家紋を付し、重厚な外観が敷地内の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014782"},{"id":"00014780","register_sub_id":"101","register_pk":"519038","name":"蔵春閣","kana":"ぞうしゅんかく","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市諏訪町一丁目1089","lat":37.94395833,"lng":139.33176111,"geo_status":"db","era":"明治45年／昭和33年・同53年・令和5年移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積222㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0584","desc":"大倉喜八郎向島別邸の旧迎賓館。木造二階建で照り起りの入母屋造を桟瓦葺とし、一階に庇が廻る。一階食堂は吹寄格天井に鳳凰を描く。二階廊下の床は都鳥と桜の大理石モザイク画で飾る。広間天井の蜀江組格天井など、随所に技巧を凝らした絢爛豪華な接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014780"},{"id":"00005115","register_sub_id":"101","register_pk":"106105","name":"早撰堂菓子店西土蔵","kana":"そうせんどうかしてんにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町1510","lat":38.22461902,"lng":139.47831231,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0192","desc":"主屋の西方，敷地の西南隅に東西棟で建つ。桁行２間半，梁間３間規模，切妻造，桟瓦葺，妻入の２階建土蔵。棟梁は主屋と同じ増田寅吉。屋根は置屋根とし，東面に戸口を設ける。鉢巻などを黒漆喰塗，扉を掛子塗とした丁寧なつくりの蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005115"},{"id":"00005116","register_sub_id":"101","register_pk":"106106","name":"早撰堂菓子店東土蔵","kana":"そうせんどうかしてんひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県村上市大町1510","lat":38.22472526,"lng":139.47836162,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積8㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0193","desc":"西土蔵の北東に位置し，敷地北辺が接道する寺町通りに妻面を見せて南北棟で建つ。桁行２間，梁間１間規模，切妻造，桟瓦葺，妻入の２階建土蔵で，南面に戸口を設ける。主屋後方に建ち，商家の構成を示す好例で，寺町通りの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005116"},{"id":"00004225","register_sub_id":"101","register_pk":"105215","name":"高島屋旧米蔵","kana":"たかしまやきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛678-1他","lat":37.7374619,"lng":138.83798777,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"15 － 0171","desc":"主屋西に位置し，昭和初期頃の建築と伝えられている。土蔵造平屋建，屋根は置屋根式で，東西棟の切妻造，桟瓦葺とし，当初は南面に扉口を設けた平入であった。外壁は漆喰塗で，現在は床・棚を備えた客室としている。上層農家の屋敷構成の一端を示す施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004225"},{"id":"00004223","register_sub_id":"101","register_pk":"105213","name":"高島屋主屋","kana":"たかしまやしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛678-1他","lat":37.73737648,"lng":138.83810618,"geo_status":"db","era":"宝暦5／明治初期増築","year":1755,"year_source":"db","year_min":1755,"year_max":1755,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積377㎡","structure_material":"木造平屋一部2階建","registered":"2004.07.23(平成16.07.23)","register_no":"15 － 0169","desc":"南北棟の民家を主体部とし，東面南端に座敷部を増築，一部２階の設置などの改造を経て，現在は旅館施設としている。主体部は差鴨居を多用した江戸後期の特徴を備え，座敷部も端正な意匠になる。正面の入母屋造玄関や座敷部妻面など，雄大な構えを見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004223"},{"id":"00004224","register_sub_id":"101","register_pk":"105214","name":"高島屋土蔵","kana":"たかしまやどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛678-1他","lat":37.73717583,"lng":138.83805483,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"15 － 0170","desc":"主屋南に位置する土蔵で，主屋の座敷部増築と同時期と思われる。土蔵造２階建，屋根は置屋根式で，南北棟の切妻造，桟瓦葺とし，１階北妻面に扉口を設ける。柱を１尺５寸間隔に並べて強固な軸部をつくる。上層農家の屋敷構成を示す施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004224"},{"id":"00013063","register_sub_id":"101","register_pk":"368352","name":"髙須家住宅主屋","kana":"たかすけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2724","lat":37.92998056,"lng":139.04895278,"geo_status":"db","era":"明治中期／明治後期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺一部金属板葺、建築面積128㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0504","desc":"信濃川河口近くの通りに東面して建つ、米売買で財をなした商家の住宅。正面側は南北棟の切妻造二階建、桟瓦葺で、背後に切妻造平屋建、金属板葺の東西棟を延ばす。南寄りに設けた大戸から土間を通し、北側に四室を並べる。通り沿いの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013063"},{"id":"00013064","register_sub_id":"101","register_pk":"368353","name":"髙須家住宅土蔵","kana":"たかすけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2724","lat":37.92998056,"lng":139.04878056,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、金属板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0505","desc":"主屋の背後に東西棟で建つ。土蔵造二階建で、全体を覆屋で囲い、屋根は土蔵と覆屋に一体で掛ける。内部は上下階とも一室で、東面一階中央に漆喰塗の両開き土戸、二階に片開き土戸を設ける。小屋組は妻面で折置組とし、地棟を配す。商家の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013064"},{"id":"00013782","register_sub_id":"101","register_pk":"507744","name":"高田家住宅主屋","kana":"たかだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市相川大工町33-1","lat":38.03521667,"lng":138.24864167,"geo_status":"db","era":"明治2年／大正9年増築","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、瓦葺、建築面積396㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"15 － 0552","desc":"上町地区の広い敷地で通りから後退し南面して建つ。切妻造平入の主体部の西に東西棟の薬品製造所を増築したＬ字形平面で桟瓦葺とし、外壁竪板張。主体部の床上部の表側に大空間のオエを配し、奥は洗練された意匠の座敷とする。明治初期に遡る上質な大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013782"},{"id":"00013783","register_sub_id":"101","register_pk":"507745","name":"高田家住宅土蔵","kana":"たかだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市相川大工町33-1","lat":38.03515,"lng":138.24875,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、覆屋付属、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"15 － 0553","desc":"主屋の南東で通り沿いに西面して建つ。桁行二間半梁間三間、土蔵造二階建で、切妻造桟瓦葺。板張の鞘で覆い、鞘の西・北面の下屋で主屋と繋ぐ。土蔵戸口に掛子塗の土戸を開き、外壁漆喰塗の腰を黒漆喰として引締める。製薬業による隆盛を伝える上質な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013783"},{"id":"00013784","register_sub_id":"101","register_pk":"507746","name":"高田家住宅門及び塀","kana":"たかだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市相川大工町33-1","lat":38.0351,"lng":138.24854722,"geo_status":"db","era":"明治前期／昭和45年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 コンクリート造門柱、間口2.0m、門扉付、塀 コンクリートブロック造、総延長32m","structure_material":"門 コンクリート造門柱","registered":"2021.06.24(令和3.06.24)","register_no":"15 － 0554","desc":"敷地南辺、主屋入口のやや西側で通りから後退して開く門と、東西にのびる塀。明治期とみられる緻密な切石積基礎上に建ち、門はコンクリート製の門柱を立てて鉄扉を開く。塀は布石上のコンクリートブロック積にモルタル仕上とする。旧家の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013784"},{"id":"00009260","register_sub_id":"101","register_pk":"194053","name":"瀧本家住宅離れ（懐徳亭）","kana":"たきもとけじゅうたくはなれ（かいとくてい）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県上越市頸城区百間町字中通711","lat":37.18681325,"lng":138.3265748,"geo_status":"db","era":"大正2年／昭和15年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"15 － 0375","desc":"敷地の南西寄りに、池に北面して建つ。木造平屋建、建築面積一三三平方メートル、入母屋造桟瓦葺で、庭側に下屋を廻らす。一二畳半の主室は、大ドコを備えて折上格天井を張り、東に前室、北に畳廊下を配する。庭園と調和した落着いた雰囲気をもつ離れである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009260"},{"id":"00012315","register_sub_id":"101","register_pk":"531639","name":"武田家住宅主屋","kana":"たけだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市大字女谷字十二 3265-1","lat":37.24458056,"lng":138.54008056,"geo_status":"db","era":"江戸後期／明治前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積243㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"15-484","desc":"柏崎市郊外の山村集落にある農家で、主屋は敷地の中央奥寄りに東面して建つ。寄棟造茅葺平入で、土間沿いに広間を取って奥に整形四間の居室を配し、土間・広間境の前に玄関、居室の裏に中門を突出する。当地方の近世民家の形式をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012315"},{"id":"00012316","register_sub_id":"101","register_pk":"531640","name":"武田家住宅土蔵","kana":"たけだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市大字女谷字十二 3265-1","lat":37.24444722,"lng":138.54035556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋一部2階建、茅葺（金属板仮葺）、建築面積60㎡","structure_material":"土蔵造平屋一部2階建","registered":"2018.05.10(平成30.05.10)","register_no":"15-485","desc":"敷地前方の片隅に北面して建つ。寄棟造茅葺平入で、土蔵造の本体の周囲に下見板張のサヤを広めに廻して本体東側に一室を設け、一体で屋根をかけ渡す独特の形式とする。田畑に囲まれた敷地の正面にあって、屋敷林とともに伝統的な農村景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012316"},{"id":"00001040","register_sub_id":"101","register_pk":"102030","name":"谷村家住宅主屋","kana":"たにむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県糸魚川市大字蓮台寺952","lat":37.03707385,"lng":137.87291639,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"木造平屋建，鉄板葺，建築面積163㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"15 － 0030","desc":"中央を「六妙の川」が流れる通称「蓮台寺谷」の中間に位置し，石垣が並ぶ川沿い道路東側に屋敷地を構える。もとは地域の庄屋の家になり，間取りは四間取りを基本とし，ダイドコロがニワにはりだす「西頸城型」民家の特徴を持ち，旧態をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001040"},{"id":"00001041","register_sub_id":"101","register_pk":"102031","name":"谷村家住宅土蔵","kana":"たにむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県糸魚川市大字蓮台寺952","lat":37.0369796,"lng":137.87300733,"geo_status":"db","era":"嘉永年間","year":1851,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"木造２階建，鉄板葺，建築面積14㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"15 － 0031","desc":"主屋の背後，敷地の南東隅に建つ。木造２階建，切妻造，平入，置屋根形式の土蔵で，風雪を考慮して，２階床の高さまで杉下見板を貼る。棟木の下面に「保食命 倉護守」の墨書がある木札が打ちつけられている。入口の切妻，妻入の庇は後補である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001041"},{"id":"00009137","register_sub_id":"101","register_pk":"164690","name":"手仕事てほどき館","kana":"てしごとてほどきかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県魚沼市大栃山字新田道上183","lat":37.35857436,"lng":139.06553137,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積181㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に東面して建つ。木造平屋1部2階建の中門造民家で、正面右手に、もと馬屋を設けていた中門が突出する。建築面積181平方メートル、寄棟造茅葺で鉄板仮葺とする。床上部は広間2室を配し、小屋は扠首組である。魚沼地方の地域的特色を示す民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009137"},{"id":"00013707","register_sub_id":"101","register_pk":"504970","name":"ときや土蔵","kana":"ときやどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県胎内市西栄町1121-5","lat":38.05082222,"lng":139.39939167,"geo_status":"db","era":"昭和9年／平成15年移築改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 551","desc":"土蔵造平屋建で切妻造桟瓦葺の置屋根を載せる。鉢巻まで漆喰で塗込め、腰を海鼠壁とする。戸前を四段掛子塗の開き戸とし、白と黒の漆喰で塗分けた窓庇を鶴の鏝絵付持送で受ける等、開口回りに意匠を凝らす。内部は二階床を抜き一室とした。通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013707"},{"id":"00010757","register_sub_id":"101","register_pk":"201592","name":"巴ヶ丘もみじ公園巴ヶ丘山荘","kana":"ともえがおかもみじこうえんともえがおかさんそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市朝日字来迎寺前600","lat":37.396832,"lng":138.776959,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0418","desc":"信濃川と渋海川に挟まれた河岸段丘上の旧別邸敷地内に建つ。寄棟造の座敷棟二棟を矩折に繋いだ平面を持ち、東棟に東面する玄関を構える。西棟は良材を用いて大床を構えた一五畳大の座敷を中心とする。越後平野を一望する景勝地に建つ、開放的な近代和風住居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010757"},{"id":"00012313","register_sub_id":"101","register_pk":"531637","name":"中原家住宅裏門及び塀","kana":"なかはらけじゅうたくうらもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市西区赤塚字屋敷添4386他","lat":37.8144,"lng":138.88408333,"geo_status":"db","era":"昭和10年頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"裏門 木造、銅板葺、間口2.8m 塀 木造、金属板葺、総延長63m","structure_material":"裏門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"15 - 0482","desc":"敷地北面の西端に開く門と北面全体を区切る総長六三メートルの塀。裏門は控柱付の腕木門で、屋根は切妻造。塀は壁を真壁造の漆喰仕上、腰下見板張とするが、裏門の周辺では板張とする。庄屋の屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012313"},{"id":"00012312","register_sub_id":"101","register_pk":"531636","name":"中原家住宅表門及び塀","kana":"なかはらけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市西区赤塚字屋敷添4386他","lat":37.81416667,"lng":138.88461389,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"表門 木造、金属板葺、間口3.2m 塀 木造、金属板葺、総延長69m","structure_material":"表門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"15 - 0481","desc":"敷地正面の中央北寄りに開く門とその左右に延びる塀で、明治天皇巡幸60周年で整備された。表門は腕木門形式で、切妻造屋根をかける。塀は切石積基壇に建ち、壁は真壁造の漆喰仕上で、腰を簓子下見板張とする。旧宿場町の品格ある街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012312"},{"id":"00012310","register_sub_id":"101","register_pk":"531634","name":"中原家住宅主屋","kana":"なかはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市西区赤塚字屋敷添4386他","lat":37.81415556,"lng":138.88425278,"geo_status":"db","era":"万延元年(1860)／昭和前期改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積386㎡、塀付","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"15 - 0479","desc":"旧北国街道沿いに敷地を構える庄屋宅。敷地中央に東面して建つ主屋は、前面に北から帳場、式台、玄関の間、相の間が並び、三の間、二の間、上段の間が矩折れで奥に連なる。出桁造、一軒繁垂木の入母屋屋根が雄大な外観をかたちづくる大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012310"},{"id":"00012311","register_sub_id":"101","register_pk":"531635","name":"中原家住宅離れ","kana":"なかはらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西区赤塚字屋敷添4386他","lat":37.81394444,"lng":138.88415556,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"15 - 0480","desc":"主屋の南西に渡廊下で接続して東面して建つ。入母屋造桟瓦葺で四周に下屋を設けて内縁を廻らし、正側面を全面ガラス戸として開放的につくる。内部は座敷飾を備える八畳と六畳、二畳の小部屋の三室からなる。近代における大庄屋の屋敷構えの発展を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012311"},{"id":"00012314","register_sub_id":"101","register_pk":"531638","name":"中原家住宅煉瓦塀","kana":"なかはらけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西区赤塚字屋敷添4386他","lat":37.81386389,"lng":138.88433889,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"煉瓦造、延長51m","structure_material":"煉瓦造","registered":"2018.05.10(平成30.05.10)","register_no":"15 - 0483","desc":"敷地の南側面の隣地境を区切る塀で、明治四二年の大火後、敷地を南側に広げた際に建てたと伝わる。両端に三尺角の煉瓦柱を建て、柱間を10連アーチの重厚な壁体でつなぐ。イギリス積の丁寧なつくりで、防火とともに庭の添景の役割も果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012314"},{"id":"00000527","register_sub_id":"101","register_pk":"101517","name":"新津記念館","kana":"にいつきねんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区旭町通1番町754-34","lat":37.91902119,"lng":139.03705104,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造３階建塔屋付，建築面積153㎡","structure_material":"鉄筋コンクリート造３階建塔屋付","registered":"1998.04.21(平成10.04.21)","register_no":"15 － 0001","desc":"新潟の石油王といわれる新津恒吉が自邸内に迎賓館として建設したもの。清水組の設計施工になる。鉄筋コンクリート造、タイル貼り、地下１階、地上３階建塔屋付で、市内中心部の高台に建ち、装飾的なコーニスと２本の煙突がランドマークになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000527"},{"id":"00005987","register_sub_id":"101","register_pk":"106972","name":"二宮家住宅一号米蔵","kana":"にのみやけじゅうたくいちごうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1106-1","lat":37.96608,"lng":139.26207,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積267㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0252","desc":"屋敷北側の前面道路を隔てた北方敷地中央部に南北棟で建つ。桁行１７間半，梁間４間半規模，切妻造置屋根，桟瓦葺，平入の木造平屋建で，東面全面に土庇を付ける。外壁は真壁造で，腰簓子下見板張，上部白漆喰塗とする。豪農の米蔵に相応しい規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005987"},{"id":"00005964","register_sub_id":"101","register_pk":"106949","name":"二宮家住宅一号土蔵","kana":"にのみやけじゅうたくいちごうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.965481,"lng":139.261841,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0243","desc":"主屋の西方に南北棟で建つ。桁行５間，梁間２間，切妻造置屋根，桟瓦葺の２階建土蔵で，東面北寄りに土庇付の戸口を設ける。石基礎，腰簓子下見板張，上部白漆喰塗で，軒裏も塗り込める。文庫蔵で，妻に家紋を浮き出し，塗戸は掛子塗とするなど丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005964"},{"id":"00005960","register_sub_id":"101","register_pk":"106945","name":"二宮家住宅大門及び塀","kana":"にのみやけじゅうたくおおもんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96564431,"lng":139.26219251,"geo_status":"db","era":"明治10／昭和10増改造","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"大門 木造平屋建、瓦葺、建築面積46㎡、塀 木造、瓦葺、延長16m","structure_material":"大門 木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0250","desc":"主屋の北側，屋敷地前面道路に沿って建つ。桁行７間，梁間１間半規模，両脇桁行２間分を部屋とした長屋門。昭和１０年に門口部を高くするとともに，大門背面側には門口の西脇から主屋方に矩折れに，石積布基礎，木造の屋根塀を延ばす特異な構えに改めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005960"},{"id":"00005969","register_sub_id":"101","register_pk":"106954","name":"二宮家住宅五号土蔵","kana":"にのみやけじゅうたくごごうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96534,"lng":139.261627,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0247","desc":"４棟並びの土蔵群の南端のもの。桁行７間半，梁間２間半規模，切妻造置屋根，桟瓦葺，平入の２階建土蔵で，四号土蔵の戸口に対応した北面の東寄りに戸口を設ける。外壁は腰海鼠壁，上部白漆喰塗とし，東妻には観音開きで掛子塗の塗戸をもつ窓を上下に並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005969"},{"id":"00005962","register_sub_id":"101","register_pk":"106947","name":"二宮家住宅作業場","kana":"にのみやけじゅうたくさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96574,"lng":139.261902,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0241","desc":"主屋の北西に位置し，東西棟で建つ。桁行３間半，梁間２間半，切妻造，桟瓦葺の木造平屋建で，屋根の南面を葺き下ろして１間幅の土庇を前面につくる。外壁は真壁造で，腰縦板張，上部白漆喰塗とし，南面中央に１間半幅の出入口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005962"},{"id":"00005970","register_sub_id":"101","register_pk":"106955","name":"二宮家住宅雑蔵","kana":"にのみやけじゅうたくざつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96566,"lng":139.261398,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0248","desc":"二号土蔵の西方，屋敷地の西端近くに位置し，南北棟で建つ。桁行３間半，梁間２間規模，切妻造置屋根，桟瓦葺，平入の平屋建土蔵で，東面に土庇を添わせて戸口を開ける。外壁は腰高く縦板を張り廻し，南妻面にのみ小窓を穿つ。屋敷地の裏庭空間を形成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005970"},{"id":"00005967","register_sub_id":"101","register_pk":"106952","name":"二宮家住宅三号土蔵","kana":"にのみやけじゅうたくさんごうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.965523,"lng":139.261673,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積65㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0245","desc":"二号土蔵の南に東西棟で並び建つ。桁行８間，梁間２間半，切妻造置屋根，桟瓦葺，平入の２階建で，北面東寄りに戸口を開ける。二号土蔵と同様に外壁腰を海鼠壁とするが，東妻壁には１階に窓を設けず，２階に２連の窓を開け，地棟端に家紋の漆喰飾りを入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005967"},{"id":"00001572","register_sub_id":"101","register_pk":"102562","name":"二宮家住宅主屋","kana":"にのみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市江南区俵柳65-2","lat":37.86184538,"lng":139.02548683,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0044","desc":"二宮家は新潟市街の南方，信濃川東岸にある農家で，主屋は大正６年の水害後に再建された。切妻造・桟瓦葺・妻入の伝統的な形式になるが，均質な柱や梁の部材に近代和風の造形がみられる。大正期の民家であるが，信濃川沿いの農村景観とよく調和している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001572"},{"id":"00005958","register_sub_id":"101","register_pk":"106943","name":"二宮家住宅主屋","kana":"にのみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96538203,"lng":139.26211929,"geo_status":"db","era":"明治17／昭和26改造","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積756㎡","structure_material":"木造平屋一部2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0239","desc":"・二宮家－新発田藩領蓮潟興野（現名称：蓮野）の名主職を勤め、後に代々庄屋格（他領の大庄屋に相当）に遇せられた家柄。いわゆる千町歩地主と呼ばれた豪農。 ・当家は俵柳二宮家（住宅：登録有形文化財）の分家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005958"},{"id":"00005959","register_sub_id":"101","register_pk":"106944","name":"二宮家住宅新奥座敷","kana":"にのみやけじゅうたくしんおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96521,"lng":139.261566,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0240","desc":"屋敷地の西南方に南北棟で建つ。寄棟造，桟瓦葺，外壁簓子下見板張の木造２階建で，東面に切妻造の玄関を付ける。１階は床付１０畳座敷を中心とし，２階南東には洋間を配する。弁天潟を望む東面と南面の開口を大きくとった開放的なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005959"},{"id":"00005961","register_sub_id":"101","register_pk":"106946","name":"二宮家住宅中門及び塀","kana":"にのみやけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96547851,"lng":139.26254557,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"中門 木造、鉄板葺、間口1.7m、塀 木造、鉄板葺、延長15m","structure_material":"中門 木造","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0251","desc":"主屋の東方に位置し，屋敷地東側を南北に区画する塀と中門。中門は門口５尺５寸幅，切妻造，鉄板葺で，塀は石基礎に土台建ちの板塀で，柱を３尺５寸間隔に立て，中途に１箇所の潜口を開ける。かって所在した前座敷や大座敷の構えを窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005961"},{"id":"00005988","register_sub_id":"101","register_pk":"106973","name":"二宮家住宅二号米蔵","kana":"にのみやけじゅうたくにごうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1107-1","lat":37.966099,"lng":139.262436,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0253","desc":"一号米蔵の東北方に位置し，東西棟で建つ。桁行１２間，梁間４間半規模，切妻造置屋根，桟瓦葺，平入の木造平屋建で，南面に土庇を付ける。一号米蔵と同様床下を設けたつくりで，小屋組はキングポストトラス。豪農の米蔵に相応しい規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005988"},{"id":"00005965","register_sub_id":"101","register_pk":"106950","name":"二宮家住宅二号土蔵","kana":"にのみやけじゅうたくにごうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.965611,"lng":139.261688,"geo_status":"db","era":"明治中期／大正4年曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積65㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0244","desc":"主屋の西方に東西棟で４棟並列して建つ土蔵のうち北端のもの。桁行８間，梁間２間半規模，切妻造置屋根，桟瓦葺，平入の２階建土蔵で，南面東寄りに戸口を設け，三号土蔵との間に両下造の庇を架ける。外壁腰を海鼠壁，塗戸を掛子塗とした丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005965"},{"id":"00001573","register_sub_id":"101","register_pk":"102563","name":"二宮家住宅農舎","kana":"にのみやけじゅうたくのうしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県新潟市江南区俵柳65-2","lat":37.86170766,"lng":139.02566031,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0045","desc":"東を正面とした細長の屋敷地奥に主屋が建ち，その前面に農舎や堆肥小屋などの附属屋がある。農舎は切妻造・桟瓦葺で，東と北に庇を設け，倉庫として用いるため柱を高くし，西側には二階部屋がある。主屋と一体となって屋敷の構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001573"},{"id":"00005963","register_sub_id":"101","register_pk":"106948","name":"二宮家住宅味噌蔵及び飯米蔵","kana":"にのみやけじゅうたくみそぐらおよびはんまいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.965816,"lng":139.261749,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0242","desc":"作業場の西に東西棟で建つ。桁行８間半，梁間２間半，切妻造置屋根，桟瓦葺の木造平屋建で，東方は味噌蔵，西方は床を上げた飯米蔵とし，南面に土庇を差し掛ける。外壁は腰簓子下見板張，上部白漆喰塗とし，連続する土庇により作業場と一体的な南面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005963"},{"id":"00005968","register_sub_id":"101","register_pk":"106953","name":"二宮家住宅四号土蔵","kana":"にのみやけじゅうたくよんごうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.965431,"lng":139.261658,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0246","desc":"三号土蔵の南に東西棟で建つ。桁行７間半，梁間２間半，切妻造置屋根，桟瓦葺，平入の２階建で，南面東寄りに戸口を設け，五号土蔵との間に両下造，桟瓦葺の庇を架ける。外壁は腰海鼠壁，上部白漆喰塗とし，東の妻壁には１階に１つ，２階に２つの窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005968"},{"id":"00005971","register_sub_id":"101","register_pk":"106956","name":"二宮家住宅涼亭","kana":"にのみやけじゅうたくりょうてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県北蒲原郡聖籠町大字蓮野1087","lat":37.96506447,"lng":139.26245035,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、鉄板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0249","desc":"屋敷地の東南部，弁天潟畔に建つ。桁行２間，梁間１間半規模，寄棟造，鉄板葺の木造平屋建で，大半を潟上に張り出す。北面に下屋を付して玄関とし，内部は６畳間で，東面に銘木を用いた床と棚を備え，南面と西面には大きく窓をとる。立地を活かした離れ茶亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005971"},{"id":"00006198","register_sub_id":"101","register_pk":"107182","name":"野澤家住宅主屋","kana":"のざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県胎内市荒井浜106","lat":38.111294,"lng":139.380508,"geo_status":"db","era":"明治22／昭和初期・30頃・40頃改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積256㎡","structure_material":"木造平屋一部2階建","registered":"2007.05.15(平成19.05.15)","register_no":"15 － 0255","desc":"廻船業で栄えた海岸付近の集落に位置し，前面通りに近接し，東面して建つ。桁行１２間，梁間８間半規模，木造平屋一部２階建，切妻造の妻入で，桟瓦葺とする。もとは石置屋根で，緩い勾配の屋根とし，漆喰塗の妻壁は梁，束を化粧で見せ，街路沿いの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006198"},{"id":"00011105","register_sub_id":"101","register_pk":"205212","name":"野澤家住宅主屋","kana":"のざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字上町1231","lat":38.156589,"lng":139.414733,"geo_status":"db","era":"明治前期／明治33頃増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積134㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0447","desc":"塩谷集落の南、通りに西面して建つ。木造二階建切妻造桟瓦葺で、内部は北を床上部とし南の幅一間の通り土間とする。外壁は下見板張とし、妻面を通りに向け南寄りに出入口を開き、正面に下屋を付すなど当地域共通の外観を見せ、街路景観に統一性を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011105"},{"id":"00011088","register_sub_id":"101","register_pk":"205195","name":"原家住宅奥土蔵","kana":"はらけじゅうたくおくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1799他","lat":37.843183,"lng":139.113382,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0430","desc":"敷地の北側に土蔵と東西並んで建つ。南を正面とし、東側の土蔵との間に平屋の倉庫を設ける。土蔵造二階建、切妻造瓦葺で置屋根形式である。外壁意匠、扉周りにスコットランド製鋼材を用いる点も隣接する土蔵とほぼ同様で、敷地景観を形造る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011088"},{"id":"00011091","register_sub_id":"101","register_pk":"205198","name":"原家住宅米蔵","kana":"はらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1794-1","lat":37.843074,"lng":139.113985,"geo_status":"db","era":"明治43／昭和26増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0433","desc":"敷地の最も東側に西面して建つ。木造平家建、切妻造瓦葺、桁行一四メートル、梁間八・〇メートルの豪壮な蔵。小屋組については間仕切りに柱のある部分には和小屋を、それ以外にはキングポストトラスを用い、それぞれを振れ止めで挟む特徴的なつくりをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011091"},{"id":"00011083","register_sub_id":"101","register_pk":"205190","name":"原家住宅主屋","kana":"はらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1798他","lat":37.842921,"lng":139.113381,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0425","desc":"敷地中央やや南寄りに南面して建つ。上客用の玄関に式台をそなえ、左手には座敷を並べる。座敷周りは比較的簡素だが材木商らしく良材を用いる。縁側の外側にガラスの建具を回して土縁とし、さらに外側に鉄柱を立て軒を支えており、当地域の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011083"},{"id":"00011085","register_sub_id":"101","register_pk":"205192","name":"原家住宅茶室","kana":"はらけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1800子他","lat":37.843181,"lng":139.11326,"geo_status":"db","era":"明治39／昭和51移築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0427","desc":"仏間北側に接続していた茶室を、敷地内の盛土した場所に移築したもの。三畳と四畳半の二つの茶室をつなぎ、それぞれに銅板葺切妻屋根を乗せる。四畳半の北面以外には円柱で支えた土庇をつける。床構えなどに良材を多く用い、上品に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011085"},{"id":"00011089","register_sub_id":"101","register_pk":"205196","name":"原家住宅道具蔵","kana":"はらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1797-1","lat":37.842798,"lng":139.113683,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺、建築面積33㎡","structure_material":"木造平屋建一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0431","desc":"主屋の東側に西面して建ち、下屋は味噌蔵と正面をそろえて葺下ろす。木造平屋建一部二階建、切妻造瓦葺。外壁の腰は下見板張、上部は真壁造としつつも鉢巻を回し、置屋根とする。小屋組は登梁で内部は柱間を板張としている。旧家の屋敷構えを引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011089"},{"id":"00011087","register_sub_id":"101","register_pk":"205194","name":"原家住宅土蔵","kana":"はらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1796他","lat":37.843156,"lng":139.113526,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0429","desc":"敷地の北側に奥土蔵と東西に並んで建つ。主屋や離れとは渡廊下で結ばれており、南を正面とする。土蔵造二階建、切妻造瓦葺で置屋根形式である。外壁は腰を煉瓦積、上部は漆喰塗とし上端に鉢巻を巡らす。入口扉まわりにはスコットランド製の鋼材を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011087"},{"id":"00011086","register_sub_id":"101","register_pk":"205193","name":"原家住宅離れ","kana":"はらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市江南区二本木1796他","lat":37.843061,"lng":139.113659,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0428","desc":"主屋の北東側に建つ隠居所で、渡廊下で主屋の他、土蔵、奥土蔵などともに接続される。木造平屋建瓦葺、寄棟で桁行六間、梁間三間、四室を田の字形に配置する。南側は縁側とし、端には手摺を設け、さらに外側に掃出しの硝子戸を立て開放的な造りとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011086"},{"id":"00011084","register_sub_id":"101","register_pk":"205191","name":"原家住宅仏間棟","kana":"はらけじゅうたくぶつまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1800子他","lat":37.843031,"lng":139.113262,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0426","desc":"主屋の北西側に接続し、木造平屋建瓦葺で寄棟屋根。東側には切妻屋根の便所と元の湯殿が取り付く。六畳の仏間西側には、間口二間、奥行四尺二寸で床を高め、仏壇を納める。その前面には虹梁を渡し、出組組物を置き、格天井を張るなど荘重な場をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011084"},{"id":"00011090","register_sub_id":"101","register_pk":"205197","name":"原家住宅味噌蔵","kana":"はらけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1797-1","lat":37.842699,"lng":139.113645,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0432","desc":"主屋の東側に西面して建ち、道具蔵との間にも平屋の倉庫を設ける。木造平屋建、切妻造瓦葺。外壁の腰は下見板張、上部は真壁造としつつも鉢巻を回し、置屋根とする。内部も真壁とし、小屋組は長大な地棟に登梁をかける。旧家の屋敷構えを引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011090"},{"id":"00011092","register_sub_id":"101","register_pk":"205199","name":"原家住宅門","kana":"はらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区二本木1798","lat":37.842739,"lng":139.113385,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0434","desc":"敷地の南辺、主屋玄関の斜め前方に建つ間口二・七メートル、奥行一・四メートルの一間薬医門である。切妻造瓦葺で、妻飾は持たず、束で化粧棟木を受ける簡素な意匠であるが、扉の一枚板など良材を用いており、風格を備えて、屋敷の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011092"},{"id":"00012514","register_sub_id":"101","register_pk":"367809","name":"肥田野家住宅主屋","kana":"ひだのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新発田市米倉2905","lat":37.893387,"lng":139.368912,"geo_status":"geocoded","era":"大正10年／昭和前期･平成2年･同18年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積258㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0488","desc":"市街地近郊の旧会津街道沿いの農家主屋で、東面して建つ。入母屋造桟瓦葺の平屋建で正面北端に玄関を設け、背面に角屋を出す。表中央に12畳半の茶の間、南端の奥に座敷を配し、東南二面に開放的な縁を廻す。旧新発田藩領の民家の近代的な展開を示す一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012514"},{"id":"00014584","register_sub_id":"101","register_pk":"515126","name":"瓢亭（旧花岡家住宅）","kana":"ひょうてい（きゅうはなおかけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区古町通八番町1448","lat":37.92461389,"lng":139.04591389,"geo_status":"db","era":"昭和9年頃／令和元年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"15 - 0579","desc":"古町の街路に面する元芸妓の住居兼稽古場。前栽と玄関を構えた二階建で寄棟造桟瓦葺。コの字平面で坪庭を囲う。一階前座敷は小唄、二階奥座敷は清元の稽古場とし、二階前座敷は客座敷に用いた。花街の住居の典型で、風情ある歴史的町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014584"},{"id":"00001328","register_sub_id":"101","register_pk":"102318","name":"平田大六家住宅主屋","kana":"ひらただいろくけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10391044,"lng":139.55043418,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺（下屋庇部分金属板葺）、建築面積504㎡","structure_material":"木造平屋建一部2階建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0034","desc":"近世初頭に当地に居を構えたとされる平田家は，元禄年間から酒造業を営み，広大な屋敷地に主屋，酒蔵等を配している。主屋は大正10年竣工の大規模な近代和風建築で，書院風意匠で統一された座敷等の各部屋や，豪壮な梁組をみせる台所等に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001328"},{"id":"00001332","register_sub_id":"101","register_pk":"102322","name":"平田大六家住宅土蔵","kana":"ひらただいろくけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10413148,"lng":139.55041031,"geo_status":"db","era":"天保6","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造2階建、瓦葺（下屋庇部分金属板葺）、建築面積29㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0038","desc":"主屋と酒蔵の中間に建つ土蔵で，棟札より天保６年の建築。桁行３間半・梁間２間半，緩い置屋根形式の石州瓦葺，外壁は荒壁仕上げである。もともと道具蔵で，内部は総２階になっており，酒造業を営んだ大規模な屋敷に欠かせない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001332"},{"id":"00001329","register_sub_id":"101","register_pk":"102319","name":"平田大六家住宅味噌蔵・米蔵","kana":"ひらただいろくけじゅうたくみそぐら・こめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10366472,"lng":139.55044362,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造2階建、瓦葺（下屋庇部分金属板葺）、建築面積79㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0035","desc":"桁行８間・梁間３間で，主屋とほぼ同時期の建築である。中央間仕切を境に北半分を味噌蔵，南半分を米蔵として使い分けている。勾配の急な置屋根形式の桟瓦葺，外壁はもと下見板壁になり，屋敷地の東南隅，主屋の南に建ち，屋敷構えの主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001329"},{"id":"00012519","register_sub_id":"101","register_pk":"367814","name":"藤木家住宅主屋","kana":"ふじきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜字下相子488","lat":38.143188,"lng":139.406952,"geo_status":"geocoded","era":"江戸末期／昭和30年代・平成18年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0493","desc":"桃崎浜の北前船主宅で、主屋は街道に妻面をみせて西面して建つ。切妻造の平屋建で街道側の下屋に吹寄せ格子を嵌める。南に土間、北に2列3室を配し、西側に並べた座敷と土間沿いの茶の間は木部透漆塗で艶やかに仕上げる。船主集落の景観の核となる町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012519"},{"id":"00012520","register_sub_id":"101","register_pk":"367815","name":"藤木家住宅醤油蔵","kana":"ふじきけじゅうたくしょうゆぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜字下相子488","lat":38.143188,"lng":139.406952,"geo_status":"geocoded","era":"江戸末期／昭和42年・平成2年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0494","desc":"敷地後方に建つ。土蔵造二階建、東西棟の切妻造で、南面を正面として西寄りに扉口を開き、東西二面にも戸口を設ける。外壁を黒漆喰塗、妻面の腰を海鼠壁とし、内部は上下階とも板敷の一室で、和小屋を組む。地域の伝統産業の様相を今に伝える大型の醸造蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012520"},{"id":"00005827","register_sub_id":"101","register_pk":"106813","name":"北條家住宅家財蔵","kana":"ほうじょうけじゅうたくかざいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市泉乙33","lat":38.02549871,"lng":138.3459579,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0225","desc":"米蔵の北隣に南面して建つ。桁行２間半，梁間２間，土蔵造２階建，切妻造，桟瓦葺とする。外壁を漆喰塗りとし，南側以外を押縁下見板張で保護する。南側は奥行１間の蔵前を設け，米蔵と味噌蔵とを繋ぎ，２棟が一体となった外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005827"},{"id":"00005806","register_sub_id":"101","register_pk":"106793","name":"北條家住宅長屋門","kana":"ほうじょうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉乙33","lat":38.0253117,"lng":138.34625122,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0223","desc":"敷地東辺に近接し，東面して建つ。桁行７間，梁間２間半，木造平屋建，寄棟造で，茅葺としては比較的規模の大きな門である。中央幅１間半を通路とし，その両側に土間２室を設ける。正面に窓を設けない質素な意匠で，農家敷地の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005806"},{"id":"00005828","register_sub_id":"101","register_pk":"106814","name":"北條家住宅味噌蔵","kana":"ほうじょうけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市泉乙33","lat":38.02550271,"lng":138.3460189,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0226","desc":"家財蔵の東隣に南面して建つ。桁行２間，梁間２間半，木造２階建，切妻造，桟瓦葺とし，南側に奥行１間半の蔵前が付く。１階は漆喰塗の味噌蔵，２階は形式的な床構えを付けた座敷とする。主屋と蔵前で繋がり，主屋と一体となった外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005828"},{"id":"00005826","register_sub_id":"101","register_pk":"106812","name":"北條家住宅米蔵","kana":"ほうじょけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市泉乙33","lat":38.02539215,"lng":138.34594189,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造及び木造2階建、瓦葺、建築面積106㎡","structure_material":"土蔵造及び木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0224","desc":"敷地西側に東面して建つ。桁行６間半,梁間３間，土蔵造２階建の米蔵の北側及び東側に，木造２階建の蔵前を矩手に設け，全体に切妻造，桟瓦葺の屋根をかける。規模の大きな米蔵で敷地の中でも際だち，大地主の屋敷としての景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005826"},{"id":"00014784","register_sub_id":"101","register_pk":"519042","name":"保阪家住宅主屋","kana":"ほさかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県上越市大字戸野目字寺畑489-1他","lat":37.12258611,"lng":138.27628611,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0588","desc":"戸野目の雁木通に位置する地主の屋敷。広大な敷地中央に南面する主屋は平屋建切妻造妻入鉄板葺で、北に台所棟を附属。南の切妻造玄関から北へ片廊下を延ばし東に２室を配す。南室は座敷で長押を打たず簡素な意匠。切妻屋根を重ねた外観が敷地内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014784"},{"id":"00014787","register_sub_id":"101","register_pk":"519045","name":"保阪家住宅温室","kana":"ほさかけじゅうたくおんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県上越市大字戸野目字寺畑489-1他","lat":37.12254167,"lng":138.2764,"geo_status":"db","era":"昭和中期、昭和59年頃改修","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造平屋建、ガラス葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0591","desc":"主屋南東に位置する果樹栽培及び園芸用の温室。切妻造妻入東西棟とし、西面に木造切妻造の前室を付す。腰高のコンクリートブロック積上の土台に柱を立て、矩勾配の合掌を組み、桁間をアングル材で繋ぐ。ガラス葺とした珍しい外観が屋敷南東の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014787"},{"id":"00014786","register_sub_id":"101","register_pk":"519044","name":"保阪家住宅道具蔵","kana":"ほさかけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市大字戸野目字寺畑489-1他","lat":37.12276944,"lng":138.27636111,"geo_status":"db","era":"文政9年（1826）／明治42年移築、平成20年改修","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積178㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0590","desc":"主屋の北に建つ家財蔵。切妻造妻入で並列した土蔵２棟に桟瓦葺の置屋根を一体で架けた大規模なもの。外壁は漆喰塗仕上とし、腰は下見板を張る。南面に戸口を設けて下屋を付し、各棟各階１室。室中央にそれぞれ独立柱を２本立てる。大型で重厚な外観の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014786"},{"id":"00014785","register_sub_id":"101","register_pk":"519043","name":"保阪家住宅離れ","kana":"ほさかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市大字戸野目字寺畑489-1他","lat":37.12268056,"lng":138.27611667,"geo_status":"db","era":"明治42年／昭和24年増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0589","desc":"主屋の西に位置する平屋建寄棟造桟瓦葺の南北棟で、主屋と渡廊下で接続。平面は２間続きの座敷で、北に納戸を角屋で延ばし、南西に矩折れに縁を廻らし、南東に便所を付す。座敷は北に床と押入を備える。縁を介して西に軒深い土縁を付し、敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014785"},{"id":"00001684","register_sub_id":"101","register_pk":"102674","name":"北方文化博物館井戸小屋","kana":"ほっぽうぶんかはくぶつかんいどごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82989756,"lng":139.15236152,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0094","desc":"主屋の北東に建ち、切妻造・桟瓦葺の簡素な建物。内部西よりに井戸があり、この水で洗濯等の作業が行われたといい、冬期の使用のため井戸を覆ったと思われる。当地方における豪農の生活の一端を伺い知る建築で、現在は茶坊として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001684"},{"id":"00001679","register_sub_id":"101","register_pk":"102669","name":"北方文化博物館いはのや","kana":"ほっぽうぶんかはくぶつかんいはのや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82906704,"lng":139.15229007,"geo_status":"db","era":"昭和20代","year":1945,"year_source":"converted","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0089","desc":"大広間の南に築かれた広大な池を持つ廻遊式庭園の南、積翠庵・是空軒と佐度看亭を結ぶ動線の中間に建っている。茶室の待合を兼ねたような小規模な建築。寄棟造の屋根は、中央桟瓦葺・周囲銅板葺の形式で、茶室の附属施設として庭園の点景にもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001679"},{"id":"00001673","register_sub_id":"101","register_pk":"102663","name":"北方文化博物館内土蔵","kana":"ほっぽうぶんかはくぶつかんうちどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82933,"lng":139.15193128,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0083","desc":"内土蔵は敷地西側に建ち、その前面にある主屋・大広間と廊下で接続している。南北棟の２階建の土蔵で、切妻造・妻入・桟瓦葺の形式。長大なため、内部には間仕切壁がある。外壁は白漆喰塗で、二階に観音扉を設ける。豪農の屋敷に相応しい雄大な倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001673"},{"id":"00001672","register_sub_id":"101","register_pk":"102662","name":"北方文化博物館大広間","kana":"ほっぽうぶんかはくぶつかんおおひろま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82944107,"lng":139.15234472,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積287㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0082","desc":"主屋の南側に中庭を挟んで並行して建ち、渡廊下で繋がっている。平屋建、入母屋造の大建築で、東面に唐破風付の玄関を設け、３２畳の大広間、各１５畳の中断の間・上段の間と続く。南の庭園側には長大な土縁を設け、雄大な構成になる豪農の接客建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001672"},{"id":"00001690","register_sub_id":"101","register_pk":"102680","name":"北方文化博物館刈羽民家","kana":"ほっぽうぶんかはくぶつかんかりわみんか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83005752,"lng":139.15267828,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0100","desc":"屋敷北東部にあり、柏崎市より移築した民家。３間取平面で、台所前方に厩をもつ出入口を突き出し、全体に茅葺屋根をかける。内部は天井を張らずに梁組をみせ、座敷だけを転根太床とするが、ほかはすべて土間床になり、全体に簡素で、古風な形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001690"},{"id":"00001686","register_sub_id":"101","register_pk":"102676","name":"北方文化博物館旧作業場","kana":"ほっぽうぶんかはくぶつかんきゅうさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83047731,"lng":139.15193366,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0096","desc":"主屋の北に位置する長大な建物。主屋建設に際して、普請用の製材のために建てられた作業所。桁行１８ｍ、南北棟の切妻造・桟瓦葺で、南面に吹放しの庇をつける。倉庫風の構造主体を持つ建築で、現在は来訪者のための売店として再利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001686"},{"id":"00001695","register_sub_id":"101","register_pk":"102685","name":"北方文化博物館米蔵","kana":"ほっぽうぶんかはくぶつかんこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83038152,"lng":139.15216331,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0105","desc":"大呂庵の一画の西辺にあり、南北棟の細長の建物。梁間は短く、長い柱を用いて、高い内部空間をつくり、食料などを貯蔵していた。切妻造・桟瓦葺、東面に庇を架け、腰部を厚めの横板張りとした真壁造で、片引戸を２箇所設けるなど、用途に適った形態をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001695"},{"id":"00001678","register_sub_id":"101","register_pk":"102668","name":"北方文化博物館佐度看亭","kana":"ほっぽうぶんかはくぶつかんさどかんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82909328,"lng":139.1520349,"geo_status":"db","era":"昭和20代","year":1945,"year_source":"converted","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0088","desc":"敷地の南西隅の小高い地にある佐度看亭は、字の如く佐渡島を眺望できるように建てられた数寄屋風の茶室建築。設計は廻遊式庭園をつくった庭師の田中泰阿弥。農家風の素朴な外観で、内部も巧みな梁組をみせるなど、近代の農家風和風建築の系譜に連なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001678"},{"id":"00001677","register_sub_id":"101","register_pk":"102667","name":"北方文化博物館三楽亭","kana":"ほっぽうぶんかはくぶつかんさんらくてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82973104,"lng":139.1518338,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0087","desc":"主屋建設後、当主であった伊藤文吉氏が自ら設計した書斎兼茶室建築で、棟梁は主屋と同じ斉藤金蔵。１辺９メートルの三角形平面を三角形の茶室と書斎および菱形の座敷にわける。部材も三角や菱形に細工するなど、三角形を基本とした特異な造形をもつ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001677"},{"id":"00001685","register_sub_id":"101","register_pk":"102675","name":"北方文化博物館集古館","kana":"ほっぽうぶんかはくぶつかんしゅうこかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.829922,"lng":139.151718,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0095","desc":"主屋の北西にあり、大規模な切妻造・平入、置き屋根式・桟瓦葺の２階建土蔵。南面のほぼ中央を開放として、東と西にわかれる。もと米蔵で、現在は展示ギャラリーとなっている。切石積の基壇、調和のとれた海鼠壁と漆喰壁、トラス組の小屋など建築の質も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001685"},{"id":"00001671","register_sub_id":"101","register_pk":"102661","name":"北方文化博物館主屋","kana":"ほっぽうぶんかはくぶつかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82964776,"lng":139.15215928,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積636㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0081","desc":"北方文化博物館は、近代土地所有制のもとに発展した豪農の伊藤家の本邸。主屋は棟札より明治２０年と判る。東を正面とする寄棟造・妻入、２階建で、奧に仏間等を持ち、構造的に通し柱を多用するなど、合理性を意識した伝統的大工技術も内包した巨大な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001671"},{"id":"00001676","register_sub_id":"101","register_pk":"102666","name":"北方文化博物館新座敷","kana":"ほっぽうぶんかはくぶつかんしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82958528,"lng":139.15181714,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0086","desc":"新座敷は敷地奥の西側にあり、総２階建、寄棟造・瓦葺の形式で、１階には半間幅の庇を廻す。数寄屋風をもととした意匠と造形であるが、良質の材を繊細に用い、内部の壁を落ち着いた砂漆喰仕上とするなど、同時期に建てられた主屋等とは異なる趣をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001676"},{"id":"00001680","register_sub_id":"101","register_pk":"102670","name":"北方文化博物館積翠庵・是空軒","kana":"ほっぽうぶんかはくぶつかんせきすいあん・ぜくうけん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82923114,"lng":139.15266011,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0090","desc":"大広間の南東、回遊式庭園を北に望むようにたたずんでいる。Ｌ字型の平面で、庭園側の茅葺屋根が積翠庵、東に延びる桟瓦葺部分が是空軒。設計は佐度看亭と同じ田中泰阿弥。草庵風の積翠庵と書院風の是空軒という、趣向の違った意匠を巧みにまとめた茶室建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001680"},{"id":"00001687","register_sub_id":"101","register_pk":"102677","name":"北方文化博物館大工場","kana":"ほっぽうぶんかはくぶつかんだいくば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83035845,"lng":139.15190338,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積140㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0097","desc":"屋敷の最も北に位置し、主屋等の建設や建物の補修のため、大工等が工作場として用いた。切妻造・平入、桟瓦葺、下見板壁の質素な平屋建の建物であるが、柱の立ちが高く、工作場としての用途をあらわしており、大規模屋敷の普請関係の数少ない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001687"},{"id":"00001693","register_sub_id":"101","register_pk":"102683","name":"北方文化博物館大呂菴","kana":"ほっぽうぶんかはくぶつかんだいろあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83050911,"lng":139.15235417,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0103","desc":"敷地の北方に位置する２階建で、物見台を持つ建物。伊藤家の分家が居住した住宅。全体に各階が高く、壁面の割付や建具も縦長の長方形をモチーフにしている。地方における２階建和風住宅の様相の一端をよく示すとともに、景観の点景にもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001693"},{"id":"00001681","register_sub_id":"101","register_pk":"102671","name":"北方文化博物館帳庫","kana":"ほっぽうぶんかはくぶつかんちょうこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.8295798,"lng":139.15274238,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0091","desc":"屋敷正面の南塀沿いにある伊藤家の家財を収納した倉庫で、昭和初期の建設と伝える。切妻造・平入で、主屋側に観音扉を設け、蔵前の庇を設ける。低い基壇上に建ち、外観は上部白漆喰、腰を海鼠壁とし、柱や梁など全体に太い部材を用い、重厚なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001681"},{"id":"00001675","register_sub_id":"101","register_pk":"102665","name":"北方文化博物館銅門及び塀","kana":"ほっぽうぶんかはくぶつかんどうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82944917,"lng":139.15282455,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、間口2.1m、塀延長20m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0085","desc":"屋敷南東の塀と湯殿を結ぶ塀と、湯殿寄りに設けられた門。大広間の玄関前空間と庭園とを効果的に区切っている。門は間口１間の棟門形式で、庭園側に控え柱を持ち、瓦棒銅板葺の屋根は緩やかに湾曲している。門・塀とも丁寧なつくりの附属建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001675"},{"id":"00001692","register_sub_id":"101","register_pk":"102682","name":"北方文化博物館常盤荘","kana":"ほっぽうぶんかはくぶつかんときわそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83037038,"lng":139.15274,"geo_status":"db","era":"万延1","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0102","desc":"敷地北東隅にあり、床の間の板裏墨書より建立年代が判る。寄棟造・桟瓦葺・平屋建で、正面左側に切妻造の玄関を持ち、かつては離れとして使われていた。最奥を床棚付の部屋とするが、材料なども含め全体に質素で、江戸末期の住宅の様相があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001692"},{"id":"00001682","register_sub_id":"101","register_pk":"102672","name":"北方文化博物館土蔵門","kana":"ほっぽうぶんかはくぶつかんどぞうもん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82978804,"lng":139.15264259,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0092","desc":"屋敷の東正面に構えられた土蔵造の門で、総２階建、桟瓦葺、北妻側を寄棟造、南妻側は門構えを介して門土蔵と連続する。豪農としての基盤を固めつつあった時期に建設されたもので、桁行約２４ｍの長大な規模を有し、今なお地域の景観の象徴になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001682"},{"id":"00001669","register_sub_id":"101","register_pk":"102659","name":"北方文化博物館新潟分館表門","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92541576,"lng":139.04035042,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造薬医門、間口2.3m","structure_material":"木造薬医門","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0079","desc":"屋敷の南西正面ほぼ中央にあり，伊藤家が購入後，別邸を整備した時に建てられた。良質の材料を用いた間口１間の腕木門形式で，背面には控え柱を建てる。銅板葺の屋根は緩やかな起りをもたせ，軒裏を木舞打とし，主屋に繋がる数寄屋風の造形としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001669"},{"id":"00001664","register_sub_id":"101","register_pk":"102654","name":"北方文化博物館新潟分館主屋","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92557107,"lng":139.04041148,"geo_status":"db","era":"明治28頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0074","desc":"主屋は長岡在住の清水氏が明治２８年頃に建てたと伝える２階建の和風建築。のちに横越町の豪農，伊藤家が購入，昭和２１年より北方文化博物館分館となった。下見板張，桟瓦葺の外観は質素だが，内部は洗練された数寄屋風で，当時の別邸のあり方を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001664"},{"id":"00001666","register_sub_id":"101","register_pk":"102656","name":"北方文化博物館新潟分館茶室","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92567407,"lng":139.04035445,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0076","desc":"主屋の北西，やや奥まった位置にあり，のちに會津八一が清行庵と命名した。伊藤家が別邸の構えを再整備した大正末期の建築と伝える。屋根はもと急勾配の茅葺で，庭園側に銅板葺の庇を廻した三帖台目の瀟洒な茶室で，数寄屋風の意匠を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001666"},{"id":"00001668","register_sub_id":"101","register_pk":"102658","name":"北方文化博物館新潟分館土蔵","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92578576,"lng":139.04059442,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0078","desc":"敷地最奥の北隅に位置する蔵で，伊藤家が建設した。切妻造・妻入・桟瓦葺・２階建で，観音扉を設けた妻面に下屋庇を設け，他の三面の１階部分外壁を海鼠壁，上部は白漆喰塗とする。全体は丁寧なつくりで，別邸の構成要素としても欠かせない倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001668"},{"id":"00001667","register_sub_id":"101","register_pk":"102657","name":"北方文化博物館新潟分館待合","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92573442,"lng":139.04059369,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、木羽葺、建築面積2.3㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0077","desc":"茶室関係の施設は，主屋と洋館の奧につくられた枯山水の庭園に面して設けられている。土蔵の南側に建つ待合は，主屋と茶室を望むよう腰掛を設け，背面の窓を大きくとる。杉皮を竹で押さえた素朴な屋根で，曲がりのある自然木を用い，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001667"},{"id":"00001665","register_sub_id":"101","register_pk":"102655","name":"北方文化博物館新潟分館洋館","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92547276,"lng":139.04051121,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0075","desc":"洋館は明治末期に購入した伊藤家が，昭和３年頃に建設した。昭和２１年から約１０年間，會津八一が起居し，現在は展示室とされている。主屋の南東に接続する総２階建の洋風建築で，外壁はドイツ風モルタル塗，建具や天井蛇腹などに昭和初期の造形が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001665"},{"id":"00001670","register_sub_id":"101","register_pk":"102660","name":"北方文化博物館新潟分館煉瓦塀","kana":"ほっぽうぶんかはくぶつかんにいがたぶんかんれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区南浜通2-561-3","lat":37.92549988,"lng":139.04060076,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、延長37m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0080","desc":"屋敷の南東部を区切る高さ約３ｍ，全長３７ｍの煉瓦塀。外側は煉瓦を見せるが，内側はバットレス状の控えと柱型を備えてモルタル塗とし，柱型の間を扁平なアーチ状にかたちづくる。煉瓦造からコンクリート造への転換期の様相が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001670"},{"id":"00001694","register_sub_id":"101","register_pk":"102684","name":"北方文化博物館東蔵","kana":"ほっぽうぶんかはくぶつかんひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.8304449,"lng":139.152649,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0104","desc":"敷地東北方、大呂庵の一画にあり、北を正面とした土蔵で、家財を収納した。２階建、切妻造・桟瓦葺で、北面に蔵前の庇を架ける。低い切石積基壇に建ち、屋根は置屋根式で、敷梁の先端を延ばして出桁を受け、深い軒をつくり、全体につくりが丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001694"},{"id":"00001696","register_sub_id":"101","register_pk":"102686","name":"北方文化博物館塀","kana":"ほっぽうぶんかはくぶつかんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82901392,"lng":139.15208305,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造、瓦葺、延長211m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0106","desc":"屋敷の周囲を取り囲む真壁造の塀で、外側は腰を簓子下見板張、小壁を砂漆喰とし、所々に連子窓を設ける。塀の外周には今も幅広い濠が部分的に残っており、濠の石垣や屋敷内の樹木などと一体となって、豪農の館に相応しい景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001696"},{"id":"00001688","register_sub_id":"101","register_pk":"102678","name":"北方文化博物館店蔵","kana":"ほっぽうぶんかはくぶつかんみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83022534,"lng":139.15204845,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0098","desc":"作業所と大工場の間に位置し、大工の道具置場として用いていた。切妻造・平入、桟瓦葺、下見板壁の平屋建で、主体部を高くして南面に長い梁間の庇を設け、収蔵空間を広くとる。現在は倉庫とされているが、大工場とともに普請関係の数少ない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001688"},{"id":"00001689","register_sub_id":"101","register_pk":"102679","name":"北方文化博物館味噌蔵","kana":"ほっぽうぶんかはくぶつかんみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83015338,"lng":139.15239304,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0099","desc":"主屋北東方に建つ桁行２８ｍの真壁造で外壁の腰を簓子下見板張とした倉庫。切妻造・平屋建であるが、身舎を高く立ち上げ両側面に庇を付けて広い内部空間をつくりだし、かつては数十樽の味噌桶を貯蔵していた。現在、床を張って食堂に利用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001689"},{"id":"00001683","register_sub_id":"101","register_pk":"102673","name":"北方文化博物館門土蔵","kana":"ほっぽうぶんかはくぶつかんもんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82966795,"lng":139.15270041,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0093","desc":"土蔵門の南側に連続し、外観は屋敷の東正面の構えとなっている。総２階建、桟瓦葺、南妻側を寄棟造とし、北妻側は間口３間で中央に内開扉を備えた門を備える。土蔵部分は伊藤家の漆器類を収納している。土蔵門とともに、地域の景観の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001683"},{"id":"00001674","register_sub_id":"101","register_pk":"102664","name":"北方文化博物館湯殿","kana":"ほっぽうぶんかはくぶつかんゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.82936814,"lng":139.15258079,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0084","desc":"大広間の南東に位置し、廊下風の通路で結ばれている。寄棟造・桟瓦葺の形式で、湯殿部分と畳敷の休憩所及び手洗いからなる。小規模な建物であるが、側廻りは腰壁押さえとして網代を付け、窓に竹格子を用いるなど、内外とも数寄屋風の意匠を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001674"},{"id":"00001691","register_sub_id":"101","register_pk":"102681","name":"北方文化博物館吉ヶ平民家","kana":"ほっぽうぶんかはくぶつかんよしがひらみんか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市江南区沢海2-6970","lat":37.83015876,"lng":139.15290966,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0101","desc":"新潟県中東部に位置する下田村から移築した民家で、刈羽民家の南隣にある。寄棟造・茅葺に石置板葺の厩を延ばした形式である。３間取平面で、広間等を床張とし、差物や貫を多用した構造である。側廻りに建つ柱列が、雪深い地にあった民家の特徴を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001691"},{"id":"00003080","register_sub_id":"101","register_pk":"104070","name":"益甚酒店土蔵","kana":"ますじんさけてんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町194","lat":38.22401608,"lng":139.47905171,"geo_status":"db","era":"明治25頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0141","desc":"酒蔵の南東方に東西棟で建つ。桁行４間梁間３間半規模，切妻造，桟瓦葺の２階建土蔵で，西妻面に入口と窓，南面に窓を開け，高い縦板張の腰の上部を真壁風に仕上げる。道具蔵で，明治４２年，主人益田甚太郎が主屋，酒造器械一式とともに買い受けたとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003080"},{"id":"00013088","register_sub_id":"101","register_pk":"368364","name":"松坂家住宅主屋","kana":"まつさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県岩船郡関川村小和田598","lat":38.13179722,"lng":139.57006111,"geo_status":"db","era":"江戸末期／昭和30年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0529","desc":"西面する大型の切妻造で、南寄りの土間前面に中門を張出す。三列構成の床上部は下手列を台所と土間、中列を茶の間等、上手を座敷列とする。土間や台所回りは軸部重厚で見応えがある。座敷前に小玄関と床付きの六畳を設ける点は特異で中門造民家の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013088"},{"id":"00013089","register_sub_id":"101","register_pk":"368365","name":"松坂家住宅文庫土蔵","kana":"まつさかけじゅうたくぶんこどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県岩船郡関川村小和田598","lat":38.13201111,"lng":139.56993611,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0530","desc":"主屋北西側に東西棟で建つ。土蔵造二階建、切妻造、置屋根形式桟瓦葺である。主屋側の東に戸口を開き、下屋を設ける。外壁漆喰塗で鉢巻を廻らし、腰高に竪板を張る。戸口に漆喰塗の鳥居枠を造る。小屋は垂木小屋組である。歴史的集落景観に寄与する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013089"},{"id":"00013087","register_sub_id":"101","register_pk":null,"name":"三浦家住宅主屋","kana":"みうらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県胎内市桃崎浜字町480","lat":38.14195833,"lng":139.40704722,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0528","desc":"南西角敷地に建つ東西棟の切妻造平屋建で、外壁の大半を簓子下見板張とする。居室は三列構成で、下手の東列に家人用玄関、台所など、中列に客用玄関と茶の間、上手の西列に次の間、上段の間などを配す。室内造作も良質で洗練され、廻船主住宅の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013087"},{"id":"00006666","register_sub_id":"101","register_pk":"107649","name":"諸橋家住宅主屋","kana":"もろはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市来伝字野尻1832乙他","lat":37.417767,"lng":139.009949,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0273","desc":"敷地東奥に西面して建つ木造２階建で、正面北端に玄関やウマヤを張り出す中門造。床上部はヒロマやザシキ、ネマなどからなる六間取で、オクザシキにはトコ等を構える。規模が大きく、座敷飾りや欄間など丁寧な造りになり、上層農家建築の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006666"},{"id":"00002534","register_sub_id":"101","register_pk":"103524","name":"諸橋家住宅主屋","kana":"もろはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市江南区茗荷谷410","lat":37.880768,"lng":139.135681,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"15 － 0114","desc":"地元で屈指の大農家の主屋で，ニワ部分を前方に突出させた中門造の平面形式をもつ。勾配の緩い桟瓦葺屋根の外観は質素だが，内部では表側に一列に並ぶ座敷の柱，長押，差鴨居などに良材を用い，古材の梁を転用した架構を現すなど，意匠的に凝った造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002534"},{"id":"00002535","register_sub_id":"101","register_pk":"103525","name":"諸橋家住宅土蔵","kana":"もろはしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区茗荷谷410","lat":37.880573,"lng":139.135712,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"15 － 0115","desc":"主屋の南に北面して建つ。切妻造，平入，置屋根形式，桟瓦葺で，戸口に幅２間の下屋を付す。内部は桁行に２分して米蔵と物置蔵とする。外部は真壁として，腰部下見板張の上に半間毎に立つ柱を見せる一方で，漆喰塗込の軒蛇腹を付して変化に富んだ構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002535"},{"id":"00003076","register_sub_id":"101","register_pk":"104066","name":"吉田家住宅座敷棟","kana":"よしだけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県新潟市秋葉区大鹿624","lat":37.7950102,"lng":139.09769864,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0137","desc":"東伍の没後，妻の帰郷に際しての改築と伝える。主屋の西南方に南北棟で建つ。切妻造，桟瓦葺の平屋建で，東面の縁側に沿って８畳２室の座敷を並べ，その南北に５畳大の小間を配する。南小間の西端に４畳大を張出して「神壇」を設けているところに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003076"},{"id":"00009749","register_sub_id":"101","register_pk":"195578","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県柏崎市大字宮川字中町2294他","lat":37.45840176,"lng":138.6106268,"geo_status":"db","era":"明治前期／昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0386","desc":"日本海沿いの通りに東面して建ち、木造二階建、切妻造妻入、桟瓦葺で正面を下屋とする。一階正面に格子をたて、二階妻壁に梁組を見せ、外壁は簓子下見板張とする。通り土間沿いに、吹抜をもつチャノマなど四室を一列に並べ、当地の伝統的な住宅形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009749"},{"id":"00003075","register_sub_id":"101","register_pk":"104065","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市秋葉区大鹿624","lat":37.79499228,"lng":139.0978092,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積306㎡","structure_material":"木造平屋一部2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0136","desc":"吉田東伍を婿養子として迎えるに当たって新築と伝える。街道に北妻面を見せたアズマダチ風民家で，東北部に切妻屋根を架けて平側に玄関を設けている点に特徴。たちの高い１５畳広間の北に土間，南に座敷と土縁を配す。棟札から「工匠若木善次郎」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003075"},{"id":"00003077","register_sub_id":"101","register_pk":"104067","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市秋葉区大鹿624","lat":37.7948274,"lng":139.09786408,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0138","desc":"主屋の南方に東西棟で建つ。桁行２間半梁間１間半規模，切妻造，桟瓦葺の２階建で，屋根は置屋根とする。当地方の土蔵に見られる外部に柱を表した造りになる。信濃川と阿賀野川に挟まれた地に位置するため，１ｍ程の土盛の上に建ち，「水倉」と呼ばれている。&nbsp;","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003077"},{"id":"00004735","register_sub_id":"101","register_pk":"105725","name":"六宜閣松風庵","kana":"ろくぎかくしょうふうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県柏崎市上輪新田23","lat":37.3305227,"lng":138.45562959,"geo_status":"db","era":"大正初期／昭和35頃移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0177","desc":"本館の北西に独立して建つ。石垣上の一段高い位置に立地し，正面切妻造，背面寄棟造，桟瓦葺で北面する。床，棚付き１０畳の座敷を中心に，東に板廊下，西に風呂，便所，上り縁を備えた土間を配す。小規模ながら吟味した良材を用いて入念に仕上げた離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004735"},{"id":"00004734","register_sub_id":"101","register_pk":"105724","name":"六宜閣本館","kana":"ろくぎかくほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県柏崎市上輪新田23","lat":37.33036252,"lng":138.45568655,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積350㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0176","desc":"海岸にほど近い庄屋の家を転用した割烹旅館の中心建物。木造，一部２階建，切妻造，桟瓦葺（もと板葺）で東面する。内部は北半上手に２列に座敷を並べ，南半下手に囲炉裏のある広間，配膳室，土間を配す。大型で格式ある構えをもち，周囲でも一際目立つ建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004734"},{"id":"00015168","register_sub_id":"101","register_pk":"530592","name":"渡部家住宅主屋","kana":"わたなべけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県東蒲原郡阿賀町八木山字八木山629","lat":37.66316667,"lng":139.53108333,"geo_status":"db","era":"嘉永3年(1850)／昭和後期改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造2階建、茅葺（鉄板仮葺)、建築面積270㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0599","desc":"会津街道沿いの集落に位置する旧本陣の主屋。敷地中央に南面して建つ寄棟造平入茅葺(鉄板仮葺)。南面中央に一二畳半の式台付玄関、東に続き座敷を設け、背面に内向きの室を配し、西端はかつての土間。式台構えや上質な座敷など江戸末期の本陣の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015168"},{"id":"00015169","register_sub_id":"101","register_pk":"530593","name":"渡部家住宅納屋","kana":"わたなべけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県東蒲原郡阿賀町八木山字八木山629","lat":37.66302778,"lng":139.53088333,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0600","desc":"主屋の南西に東面して建つ農作業用の倉庫。木造平屋建で切妻造鉄板葺、和小屋とする。正側面腰壁に下見板を張り、背面は全面板張とする。内部は土間、壁は中塗仕上。旧街道沿いの石積擁壁上の小高い場所に建ち、主屋とともに地域の歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015169"},{"id":"00006668","register_sub_id":"101","register_pk":"107651","name":"木間家住宅納屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市松尾字倉下776","lat":37.4115654,"lng":139.0089626,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、茅葺、建築面積32㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0275","desc":"主屋の西南に位置し、納屋南側には水田が広がる。桁行３間梁間２間規模の木造２階建。寄棟造妻入の茅葺で、妻側を兜造風に切り欠き、軒を出桁造で凝った造りとする。外壁は土壁で、養生のために仮板を張る。主屋と一体となり、農村景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006668"},{"id":"00006669","register_sub_id":"101","register_pk":"107652","name":"木間家住宅蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市松尾字倉下776","lat":37.4116886,"lng":139.0088589,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、鉄板葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0276","desc":"敷地の西寄り、主屋西方に位置する。桁行３間半梁間２間、土蔵造２階建、切妻造鉄板葺の置屋根とする。内部は１階を３室に分けて米や家財道具を納め、２階は側・背面壁に接して押入を作り、什器等を保管する。板張の雪囲いを周囲に巡らし、正面に下屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006669"},{"id":"00001568","register_sub_id":"101","register_pk":"102558","name":"太古山日長堂主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区新崎2-4-57","lat":37.92485417,"lng":139.15306727,"geo_status":"db","era":"18世紀中期","year":1750,"year_source":"estimated","year_min":1731,"year_max":1770,"year_label":"18世紀中期","structure":"木造平屋建、鉄板葺、建築面積349㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0040","desc":"この地の庄屋を務めた古山家の主屋で，広大な敷地のほぼ中央に南面して建つ。Ｔ字型平面で，前側に広間や座敷等があり，背面に居室部が突出する。正面に破風をみせた屋根をあげた撞木造風の壮大な外観は，都市化の進む景観の中の歴史的要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001568"},{"id":"00001569","register_sub_id":"101","register_pk":"102559","name":"太古山日長堂仏蔵","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区新崎2-4-57","lat":37.92497113,"lng":139.15294391,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0041","desc":"主屋北西に建つ総二階建の蔵で，切妻造・桟瓦葺，西に庇を設け，出入り口とする。一階は板床，格天井で壁面に仏壇を設け，二階を物置とする。古山家の持仏堂的な機能を有していた。主屋と一連の施設で，旧家の仏座のあり方を示す要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001569"},{"id":"00000761","register_sub_id":"101","register_pk":"101751","name":"有藤家住宅","kana":"ありとうけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県高岡市吉久2-3-13","lat":36.77940471,"lng":137.05567386,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造２階建，瓦葺，建築面積195㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"16 － 0045","desc":"加賀藩の蔵米の積出港として栄えた吉久地区にある商家。間口６間半と広く，内部は２列３室の居室部になる。玄関奥の「オイ」は独特の梁組を見せる構成になる。地元の大工の手になり，全体として質は高い。年代は新しいが，基準的な外観意匠の町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000761"},{"id":"00008108","register_sub_id":"101","register_pk":"132506","name":"伊東家住宅（旧松下家住宅）主屋","kana":"いとうけじゅうたく（きゅうまつしたけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県高岡市中田字木村4760","lat":36.68182256,"lng":137.02004392,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積179㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0085","desc":"南面の庭園側に縁とテラスを付ける住宅。傾斜の強い入母屋屋根を中心に、切妻屋根や破風を付け、大きな突き上げ状屋根窓を開ける。中廊下型平面やハーフティンバー風の妻面処理など、山田醇の作風がよく示される。内部は青や鶯色等の色壁で、斬新な感性が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008108"},{"id":"00011118","register_sub_id":"101","register_pk":"205225","name":"金作家住宅主屋","kana":"かなさくけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市内免1-53他","lat":36.752371,"lng":137.007498,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0117","desc":"高岡の明治期の景観を今に伝える町家。細長い間口四間の敷地に建ち、正面北端に玄関を開いて土間を通す。近隣に多い一列四段型ではなく二列四段型の平面構成をとる。正面下屋庇を厚板葺とし、笄を載せるのも地域の特徴。座敷の彫刻欄間等にも意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011118"},{"id":"00011120","register_sub_id":"101","register_pk":"205227","name":"金作家住宅西土蔵","kana":"かなさくけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県高岡市内免1-53他","lat":36.75247,"lng":137.007292,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0119","desc":"東土蔵の背面側に接して建つ。背面側の置屋根を東土蔵側にそのまま伸ばして一体的に覆屋状にかける。外壁は全面漆喰塗で、妻側にある扉口に鳥居枠を設ける他は外壁に装飾的要素をほとんど持たず、土扉も設けないなど、全体的に簡素な作りとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011120"},{"id":"00011119","register_sub_id":"101","register_pk":"205226","name":"金作家住宅東土蔵","kana":"かなさくけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市内免1-53他","lat":36.752417,"lng":137.007387,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0118","desc":"主屋の背面側に庭を介して建つ。主屋に面した東面に扉口を開き、下屋を付す。主体部の屋根は西土蔵と一体で覆屋状にかける。扉周りは鳥居枠を設け、両側に梁形を伸ばし、扉両脇は梁形より下部を黒漆喰塗とするなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011119"},{"id":"00000571","register_sub_id":"101","register_pk":"101561","name":"旧内山家住宅にわ（作業場）","kana":"きゅううちやまけじゅうたく（さぎょうば）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72909756,"lng":137.20756471,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造平屋建一部２階建，瓦葺，建築面積92㎡","structure_material":"木造平屋建一部２階建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0030","desc":"主屋の北方東よりに建つ切妻造，桟瓦葺で東西棟の平入の建物。使用人の仕事場として使われた建物で，裏側に雪囲いの材料等をしまう物置がある。東西に棟を一段低くした小部屋を設ける。この地方の豪農の暮らしぶりを知る上で役立つ建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000571"},{"id":"00000579","register_sub_id":"101","register_pk":"101569","name":"旧内山家住宅井戸上屋","kana":"きゅううちやまけじゅうたくいどうわや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72908702,"lng":137.20742142,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造平屋建，瓦葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0038","desc":"主屋の北方，人力車おき場等とにわ（作業場）の間にある井戸に屋根をかけたあずまや風の建物。４隅にそれぞれ３本の柱を立て，柱の頭を大斗のような形につくり出し，屋根頂部の装飾にも工夫を凝らす等，珍しい意匠・形態をもった建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000579"},{"id":"00000574","register_sub_id":"101","register_pk":"101564","name":"旧内山家住宅表門","kana":"きゅううちやまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72904066,"lng":137.20683982,"geo_status":"db","era":"慶応4","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造薬医門，瓦葺，塀付属","structure_material":"木造薬医門","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0033","desc":"屋敷地西境のほぼ中央に建つ比較的に規模が大きな薬医門。左右に折り曲がりの屋根塀が附属する。もと茅葺で，昭和１６年に屋根を桟瓦葺にかえた。現存する江戸時代の農家に建てられた門としては珍しい事例で，往時の当家の繁栄が知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000574"},{"id":"00000576","register_sub_id":"101","register_pk":"101566","name":"旧内山家住宅北門","kana":"きゅううちやまけじゅうたくきたもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72912917,"lng":137.2077649,"geo_status":"db","era":"慶応年間","year":1866,"year_source":"estimated","year_min":1865,"year_max":1868,"year_label":"慶応年間","structure":"木造棟門，瓦葺","structure_material":"木造棟門","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0035","desc":"屋敷地の北境の東よりに建つ棟門形式の門。内山家は藩主鷹狩りの際に宿所とされたと伝える家で，かつて屋敷地の北方が丘陵状になっており，その一帯が狩り場であったと推定される。この門は狩り場に通じる位置にあり，往時の様子を忍ばせる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000576"},{"id":"00000566","register_sub_id":"101","register_pk":"101556","name":"旧内山家住宅主屋","kana":"きゅううちやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72892898,"lng":137.20729498,"geo_status":"db","era":"慶応4・明治20頃・明治末","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建一部２階建，瓦葺，建築面積860㎡","structure_material":"木造平屋建一部２階建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0025","desc":"江戸末期に建てられた大規模な農家で，明治２０年代末頃に南方の表座敷・書院等を，明治末年頃に東方の桜香の間等を増築して現在の姿となった。長大な部材を用いた大広間や銘木を駆使した書院等の意匠は優れ，それぞれには時代の違いがよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000566"},{"id":"00000572","register_sub_id":"101","register_pk":"101562","name":"旧内山家住宅人力車おき場・車夫小屋・炭小屋","kana":"きゅううちやまけじゅうたくじんりきしゃおきば・しゃふごや・すみごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72909545,"lng":137.20727812,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造平屋建，瓦葺，建築面積58㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0031","desc":"主屋の北方西よりに接続して建つ細長い南北棟の平入建物。屋敷地の正面からみると，主屋の北にのびて表庭と裏の作業空間を区切り視線をさえぎる役割を果たしており，屋敷構えの主要な構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000572"},{"id":"00000578","register_sub_id":"101","register_pk":"132564","name":"旧内山家住宅背戸の門","kana":"きゅううちやまけじゅうたくせどのもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72857918,"lng":137.2075626,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造棟門，瓦葺","structure_material":"木造棟門","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0037","desc":"屋敷地の東側境の南より，土蔵の南方に建つ小規模で簡素な棟門形式の門。東門とともに屋敷地東方の果樹園や畑に通じる門としてつくられたが，茶室三入庵等とともに広大な庭の点景としての役割も果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000578"},{"id":"00000569","register_sub_id":"101","register_pk":"101559","name":"旧内山家住宅茶室三入庵","kana":"きゅううちやまけじゅうたくちゃしつさんにゅうあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72848224,"lng":137.20732238,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積20㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0028","desc":"主屋の南方，敷地の南端に近い位置に建つ茶室。昭和１６年に内山家から他所に移築されたが，昭和５６年に再び内山家に戻った。藪内流家元の指導で京都の棟梁を招いてつくったと伝える。手堅くまとまった意匠になる茶室で，水屋の舟底天井等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000569"},{"id":"00000568","register_sub_id":"101","register_pk":"101558","name":"旧内山家住宅茶室夜雨廰","kana":"きゅううちやまけじゅうたくちゃしつやうちょう","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72869718,"lng":137.20759632,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0027","desc":"土蔵の南に接続して建つ。明治１２年につくられた書斎を明治末年に改修して茶室とした。接続する土蔵と対照的な広い開口部をもつ開放的なつくりは茶室としては珍しく，もと書斎であったことがうかがえる。色壁を使った室内意匠にもみどころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000568"},{"id":"00000567","register_sub_id":"101","register_pk":"101557","name":"旧内山家住宅土蔵","kana":"きゅううちやまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72880465,"lng":137.20767007,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"土蔵造２階建，瓦葺，建築面積184㎡","structure_material":"土蔵造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0026","desc":"主屋の東方，屋敷地境に接して建つ南北棟の平入の土蔵。内部は，南から上の蔵，中の蔵，下の蔵，味噌蔵に別れる。米・夜具等を納めた蔵と伝え，豪農の家の屋敷構えを知る上で欠くことのできない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000567"},{"id":"00000570","register_sub_id":"101","register_pk":"101560","name":"旧内山家住宅にわとり小屋","kana":"きゅううちやまけじゅうたくにわとりごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.7290217,"lng":137.20783233,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造平屋建，瓦葺，建築面積32㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0029","desc":"屋敷地の東北隅近くに建つ切妻造，平入，桟瓦葺の小規模な建物。意匠は簡素だが，石を並べて一段高く築いた基礎の上に建ち，壁を漆喰で仕上げるなど鶏用としては破格の扱いで，他に類例の少ない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000570"},{"id":"00000577","register_sub_id":"101","register_pk":"101567","name":"旧内山家住宅東門","kana":"きゅううちやまけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72893952,"lng":137.2077944,"geo_status":"db","era":"明治末","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末","structure":"木造棟門，瓦葺","structure_material":"木造棟門","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0036","desc":"屋敷地の東側境，にわとり小屋と土蔵の中間の位置に建つ棟門形式の門。かつては屋敷地の東方に果樹園や畑が広がっており，この門はそこに通じる門として使われていた。簡素ながら，往時の屋敷周辺の様子を示す建物として意義がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000577"},{"id":"00000575","register_sub_id":"101","register_pk":"132563","name":"旧内山家住宅塀中門","kana":"きゅううちやまけじゅうたくへいちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.7289943,"lng":137.20693464,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造，塀付属","structure_material":"石造","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0034","desc":"主屋の西にある客用便所に接続して建つ折り曲がりの塀に開かれた門。石造の柱の上部に石造の笠木をのせた簡略な形式の門口に木戸を入れた特異な意匠になる。塀は腰まで自然石を積み上部を切石積みとする形式で，座敷側の庭と前庭を区切る役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000575"},{"id":"00000573","register_sub_id":"101","register_pk":"101563","name":"旧内山家住宅もみ倉","kana":"きゅううちやまけじゅうたくもみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市宮尾903","lat":36.72924296,"lng":137.20726548,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建，瓦葺，建築面積40㎡","structure_material":"土蔵造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0032","desc":"炭小屋の西北方に建つ平屋建の土蔵。石積みの基礎の上に建ち，腰から下は壁の漆喰仕上げの色をかえる。屋根は置屋根形式である。長庫（ながぐら），木納屋とも呼ばれる。東方の土蔵と比較すると簡素だが，豪農の屋敷構えを示す建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000573"},{"id":"00010439","register_sub_id":"101","register_pk":"199398","name":"旧大谷家住宅表門","kana":"きゅうおおたにけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672673,"lng":136.909873,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造、瓦葺、間口3.1m","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0106","desc":"間口一〇尺の一間薬医門で、五平の柱を立て、雲形肘木の組物で虹梁大瓶束笈形付の妻飾を受ける。軒は二軒繁垂木で、切妻造屋根と両脇潜戸の屋根は桟瓦葺とする。透彫欄間付の板扉も手の込んだ施工で、屋敷正面中央の表構えに相応しい形式と質の高さを誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010439"},{"id":"00010438","register_sub_id":"101","register_pk":"199397","name":"旧大谷家住宅作業納屋","kana":"きゅうおおたにけじゅうたくさぎょうなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672914,"lng":136.909864,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0105","desc":"敷地東辺に建つ。桁行七間梁間二間半、一部二階建の切妻造桟瓦葺で、西面に下屋を設ける。南五間分は土間で吹抜けの作業空間とし、二階の根太床のある北寄り二間分に道具を収納した。真壁造の外壁は東面と北と南の側面を下見板張とし、積雪地らしい形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010438"},{"id":"00010434","register_sub_id":"101","register_pk":"199393","name":"旧大谷家住宅主屋","kana":"きゅうおおたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672801,"lng":136.90956,"geo_status":"db","era":"昭和10／昭和20改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0101","desc":"南東を正面とする桁行四間半梁間七間、切妻造桟瓦葺の妻入りで、三面に幅一間の下屋を付け、北西隅に後設の離れ座敷などが接続する。平面は三列構成で、良材を用いた上質な造作になる。いわゆるアズマダチ形式住宅で、当地の邸宅に相応しい外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010434"},{"id":"00010435","register_sub_id":"101","register_pk":"199394","name":"旧大谷家住宅納屋","kana":"きゅうおおたにけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672651,"lng":136.909699,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0102","desc":"主屋の前方に対面して建つ。桁行五間梁間二間半の二階建、切妻造平入りで、北面に下屋を設ける。屋根は桟瓦葺とし、外壁は漆喰塗と下見板張を併用する。内部は各階とも二室に分かれ、異なる内装とする。丁寧な造作の附属屋で、当地の屋敷構えの特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010435"},{"id":"00010437","register_sub_id":"101","register_pk":"199396","name":"旧大谷家住宅灰小屋","kana":"きゅうおおたにけじゅうたくはいごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672896,"lng":136.909724,"geo_status":"db","era":"昭和10／平成25改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積1.4㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0104","desc":"桁行梁間とも約四尺で、切妻造桟瓦葺、外壁は板張で上部を漆喰塗とする。北面は上部を板扉、下部に取出口を付ける。内壁と床は土塗として防火性をもたせる。南側に建つ風呂場の灰を集積する小規模な施設で、伝統的な農村生活の一端を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010437"},{"id":"00010436","register_sub_id":"101","register_pk":"199395","name":"旧大谷家住宅風呂場","kana":"きゅうおおたにけじゅうたくふろば","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県小矢部市水落35","lat":36.672858,"lng":136.909739,"geo_status":"db","era":"昭和10／平成25改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積9.8㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0103","desc":"主屋の東方にある外風呂。切妻造桟瓦葺、簓子下見板張で、正面を主屋に向ける。桁行一間半梁間一間の規模で、左端に設けた焚口は三方が開放になる。右側面の低い下屋は犬小屋で、堅牢な形式としている。昭和前期の暮らしの有り様を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010436"},{"id":"00010440","register_sub_id":"101","register_pk":"199399","name":"旧大谷家住宅塀","kana":"きゅうおおたにけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県小矢部市水落35","lat":36.67301967,"lng":136.90965983,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造、瓦葺、総延長153m","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"16 － 0107","desc":"表門両側の南辺、東辺及び北辺を囲う。南塀は六尺柱間、東塀と北塀は五尺五寸柱間で、桟瓦葺とする。南塀は大振りの玉石二段積基礎で、大和張の竪板と虫食い板欄間にするが、東塀と北塀は簡素な形式になる。当地方の典型的な塀で田園風景とよく調和している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010440"},{"id":"00000580","register_sub_id":"101","register_pk":"101570","name":"旧金岡家住宅主屋","kana":"きゅうかなおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市新庄町1-5-24","lat":36.70186261,"lng":137.25427405,"geo_status":"db","era":"明治初期／大正期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建一部２階建，瓦葺，建築面積437㎡","structure_material":"木造平屋建一部２階建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0039","desc":"薬種業を営んだ家の主屋で，道路に東面する大規模町家。北西に隣接して新屋が建てられた時に接続部等の一部を増築したが，概ね建築当初の様子をよくとどめている。通りに面した広いミセや銘木・色付き壁等を駆使した座敷の室内意匠等に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000580"},{"id":"00000581","register_sub_id":"101","register_pk":"101571","name":"旧金岡家住宅新屋","kana":"きゅうかなおかけじゅうたくしんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県富山市新庄町1-5-24","lat":36.70203931,"lng":137.2541316,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，瓦葺，建築面積246㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0040","desc":"主屋の北西方に接続して建つ接客用の建物。切妻造，妻入の奥行の長い建物で正面に玄関が取り付いた意匠に特徴がある。良質の檜や欅，各種の銘木，趣向を凝らした壁や襖等を用いた室内の意匠にもみどころがある。設計は，清水組の西原兵治と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000581"},{"id":"00014589","register_sub_id":"101","register_pk":"515131","name":"旧金岡家住宅道具蔵","kana":"きゅうかなおかけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市新庄町一丁目37-21","lat":36.70188611,"lng":137.25358611,"geo_status":"db","era":"明治13年頃／大正後期頃・昭和60年改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積137㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"16 - 0162","desc":"新庄町中心部に位置する薬種商の道具蔵。二階建切妻造平入桟瓦葺の東西棟で、南に二箇所出入口を設けて下屋を付し戸前とする。内部各階は一室の板敷で棟通り中央の独立柱は舟肘木で地棟を支持。外壁腰はモルタル洗出仕上で石貼風にみせる重厚な大規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014589"},{"id":"00000582","register_sub_id":"101","register_pk":"101572","name":"旧金岡家住宅土蔵","kana":"きゅうかなおかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市新庄町1-5-24","lat":36.70175623,"lng":137.25405768,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積35㎡","structure_material":"土蔵造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0041","desc":"主屋の東南方に建つ比較的に小規模な切妻造２階建，平入の土蔵。妻に母屋桁と棟木をみせ，隣接する土蔵と意匠をかえている。薬種業関連の物品を納めた建物で，屋敷構えの主要な構成要素のひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000582"},{"id":"00000584","register_sub_id":"101","register_pk":"101574","name":"旧金岡家住宅塀","kana":"きゅうかなおかけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市新庄町1-5-24","lat":36.70196538,"lng":137.25433716,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造，瓦葺，延長77.1m","structure_material":"木造","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0043","desc":"屋敷地の北面境から西面境にかけて庭を囲うようにめぐらされた瓦葺の屋根塀。西面は，門に接続して左右にのびた形で，南端は主屋に接続する。石製の基礎の上に建ち腰に板を張る丁寧なつくりで，門とともに往時の繁栄の様子を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000584"},{"id":"00000583","register_sub_id":"101","register_pk":"101573","name":"旧金岡家住宅門","kana":"きゅうかなおかけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市新庄町1-5-24","lat":36.70197981,"lng":137.25440207,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造薬医門，瓦葺","structure_material":"木造薬医門","registered":"1998.07.23(平成10.07.23)","register_no":"16 － 0042","desc":"道路に東面して主屋の北に建つ瓦葺の薬医門。賓客用に開かれた門で，道からわずかに後退して建ち，新屋へと通じる。屋根にむくりを付けるなど意匠は新屋と類似する。薬種業を営んだ家の往時の繁栄の様子をよく示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000583"},{"id":"00011931","register_sub_id":"101","register_pk":"211079","name":"旧田中家住宅主屋","kana":"きゅうたなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県射水市本江字足洗2280","lat":36.758659,"lng":137.173387,"geo_status":"db","era":"大正6年頃／昭和6年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積266㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"16-133","desc":"田中家は網元に端を発し、漆器類の商いや金融業等で財を成した家。木造二階建、入母屋造桟瓦葺で、三方に玄関、茶室便所、化粧の間をそれぞれ突出させる。平面は三列九室で、ヒノキの総柾材による式台玄関をはじめとして、軸部材・造作共に贅を尽くす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011931"},{"id":"00011934","register_sub_id":"101","register_pk":"211082","name":"旧田中家住宅庭門","kana":"きゅうたなかけじゅうたくにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県射水市本江字足洗2280","lat":36.758659,"lng":137.173527,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"16-136","desc":"主屋表玄関の左脇に位置し、主屋の南東側に広がる内庭と通路を画す門。木造、桟瓦葺の腕木門で、腕木下には彫刻持送りを設け、まぐさ上部は捻子竪格子とする。簡素ではあるが、敷地景観を整える上で欠くことのできない門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011934"},{"id":"00011932","register_sub_id":"101","register_pk":"211080","name":"旧田中家住宅離れ","kana":"きゅうたなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県射水市本江字足洗2280","lat":36.75879,"lng":137.1733,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"16-134","desc":"主屋の北西端に接続する。桁行五間、梁間二間の木造平屋建で、東縁を南北に通し、西側に南から八畳、台所、浴室を配す。浴室天井をヒノキの総柾材で四角錐状に打上げ、中央には数寄屋風意匠の繰抜き彫刻を用いた換気口とするなど、意匠を凝らした離れである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011932"},{"id":"00013986","register_sub_id":"101","register_pk":"508246","name":"旧野村家住宅一番蔵（城端蔵回廊）","kana":"きゅうのむらけじゅうたくいちばんぐら（じょうはなくらかいろう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市城端字大工町579-2他","lat":36.51461667,"lng":136.90196389,"geo_status":"db","era":"明治後期／平成5年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0158","desc":"城端別院門前町に建つ元呉服商の衣装蔵。土蔵造二階建、切妻造桟瓦葺平入で、五色の石垣上に建つ。外壁は下見板張、軒は漆喰塗込、掛子塗戸の窓は霧除庇で覆う。正面の腰は黒漆喰地に折入菱を表し、戸口には掛子塗戸を鏝絵で飾る。造りも丁寧な豪商の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013986"},{"id":"00013988","register_sub_id":"101","register_pk":"508248","name":"旧野村家住宅雑蔵（城端蔵回廊）","kana":"きゅうのむらけじゅうたくざつぐら（じょうはなくらかいろう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市城端字大工町579-3他","lat":36.51451389,"lng":136.90192222,"geo_status":"db","era":"明治後期／平成5年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積68㎡、石門付","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0160","desc":"一番蔵の南側に雁行して建つ元呉服商の雑用蔵。土蔵造二階建、切妻造桟瓦葺で、石垣上に建ち背面北寄りに下屋を付す。背面は下見板張で、腰を煉瓦張、軒際の窓は漆喰塗の箱枠に鉄格子を嵌める。通りに石造欠円アーチの門を開く。豪商の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013988"},{"id":"00013987","register_sub_id":"101","register_pk":"508247","name":"旧野村家住宅二番蔵（城端蔵回廊）","kana":"きゅうのむらけじゅうたくにばんぐら（じょうはなくらかいろう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市城端字東上町577-1他","lat":36.51463611,"lng":136.90197222,"geo_status":"db","era":"明治後期／平成5年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積79㎡、石門付","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0159","desc":"一番蔵北隣に雁行して建つ元呉服商の道具蔵。土蔵造二階建、切妻造桟瓦葺平入で、五色の石垣上に建つ。外壁は下見板張で、背面通沿いに上下五箇所の窓を設け、霧除庇で覆う。正面は一番蔵と意匠を揃える。内部一階の壁は柱に板落とし込み、堅牢な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013987"},{"id":"00011115","register_sub_id":"101","register_pk":"205222","name":"旧馬場家住宅壱番蔵及び弐番蔵","kana":"きゅうばばけじゅうたくいちばんぐらおよびにばんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市東岩瀬町107-2","lat":36.75716,"lng":137.228281,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造3階建、瓦葺、建築面積157㎡","structure_material":"土蔵造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0114","desc":"主屋の北西寄りに南面して建つ二戸前の塗籠土蔵。内部は三階建で、土扉を鳥居枠、四段掛子塗とするなど細かな意匠を持つ。外壁は腰部を布石積洗出仕上げとし、戸前は梁間一間半の下屋形式で、主屋に矩折れに接続する。廻船業で繁栄した歴史を物語る上質な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011115"},{"id":"00011116","register_sub_id":"101","register_pk":"205223","name":"旧馬場家住宅米蔵","kana":"きゅうばばけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市東岩瀬町107-2","lat":36.75716,"lng":137.228085,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積267㎡","structure_material":"土蔵造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0115","desc":"敷地西北隅の最奧部に建つ。桁行八間梁間七間の大規模な平屋建土蔵。南面に吹き放ちの下屋を設け、扉二所を開く。河港側にあたる西面には鞘板壁を設ける。敷地内の他の蔵と比較して簡素な意匠になるが、内壁一面に貫を多く入れるなどの特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011116"},{"id":"00011113","register_sub_id":"101","register_pk":"205220","name":"旧馬場家住宅主屋","kana":"きゅうばばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市東岩瀬町107-2","lat":36.757016,"lng":137.228581,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積512㎡、塀付","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0112","desc":"明治六年の大火後に再建したと伝える。東面する三列四段の正方形平面を中心に、北寄りに土間を通し、西側に居室を張り出す。内装は漆塗を施す数寄屋造。東岩瀬の中でも最大規模の住宅で、豪壮な正面構えで東岩瀬の港町の景観を構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011113"},{"id":"00011117","register_sub_id":"101","register_pk":"205224","name":"旧馬場家住宅西門及び西塀","kana":"きゅうばばけじゅうたくにしもんおよびにしへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市東岩瀬町107-2","lat":36.75705431,"lng":137.2279908,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口2.5m 塀 木造、瓦葺、延長37m","structure_material":"門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0116","desc":"敷地西側を画す。中央やや南寄りに位置する西門は一間腕木門で桟瓦葺の起り屋根をかける。両側の塀は玉石積の上に基礎石を置き、腰竪板張に小壁を白漆喰塗、桟瓦葺とする。廻船問屋の住宅として、河港側を上質の屋敷構えとしたことが伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011117"},{"id":"00011114","register_sub_id":"101","register_pk":"205221","name":"旧馬場家住宅前蔵","kana":"きゅうばばけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県富山市東岩瀬町107-2","lat":36.757093,"lng":137.228639,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造3階建、瓦葺、建築面積47㎡","structure_material":"土蔵造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0113","desc":"主屋の北隣りに、平側を街路に面して建つ土蔵造三階建。入口は主屋側に設け、土間を介して接続する。街路側には一、二階通しの縦長窓を二所設け、外側を引違ガラス戸の出窓で覆う。鳥居枠に四段の掛子塗とする両開土扉の扉口廻りなどに丁寧な仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011114"},{"id":"00010130","register_sub_id":"101","register_pk":"197963","name":"齋賀家住宅主屋","kana":"さいがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県南砺市井波字八日町3036他","lat":36.559984,"lng":136.971175,"geo_status":"db","era":"江戸末期／大正期・昭和後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0094","desc":"井波別院瑞泉寺の参道に東面する。二階正面に格子をたて、両端に袖壁を設けるほか、庇を厚板葺として軒先に霧除けのガンギを設け、地方的特色を示す。内部は右手に土間を通し、揚戸を残すミセ、上部吹抜けのオイ等を並べる。門前町の往時の景観を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010130"},{"id":"00010131","register_sub_id":"101","register_pk":"197964","name":"齋賀家住宅土蔵","kana":"さいがけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市井波字八日町3036他","lat":36.559897,"lng":136.970989,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"16 － 0095","desc":"敷地西奥に東西棟で建つ。土蔵造二階建、桁行九・一メートル梁間四・四メートル、切妻造、置屋根式の桟瓦葺で、南面に下屋を設け、中央の戸口に扉を開く。外壁は漆喰塗で腰に簓子下見板を張り、正背面に鉄扉付きの窓を並べ鳥居枠で飾る。建ちの高い大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010131"},{"id":"00000529","register_sub_id":"101","register_pk":"101519","name":"佐野家住宅１番の蔵","kana":"さのけじゅうたくいちばんのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74584449,"lng":137.00829266,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造２階建，瓦葺，建築面積20㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0020","desc":"明治３３年の高岡大火の教訓から，屋敷地全体を防火的な構えとする居宅建物群の一つ。このうち，敷地背後には４棟の蔵を並列して建て，防火帯とする。１番の蔵は北端に建つ土蔵造，２階建の小規模な建物で，南隣の２番の蔵とも一体的な造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000529"},{"id":"00000401","register_sub_id":"101","register_pk":"101391","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74761924,"lng":137.00936873,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積112㎡","structure_material":"土蔵造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"16 － 0016","desc":"明治３３年の高岡大火直後の再建で，屋敷全体を防火に配慮した構成とする。主屋は桁行７間半，梁間５間の大型の町家で，正面に一間の土庇が付く。２階は大壁の黒漆喰塗とし，銅板張の防火戸をつける。大型の土蔵造町家の好例で，全体的に保存も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000401"},{"id":"00000528","register_sub_id":"101","register_pk":"101518","name":"佐野家住宅茶室","kana":"さのけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74577339,"lng":137.00843068,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0019","desc":"明治３３年の高岡大火後，再建主屋の背後に設けられた中庭南側に建つ小規模な茶室。明治時代から大正時代にかけて豪商の居宅に付属施設として建てられた茶室の好例で，簡素な外観ながら高岡商人の文化的な生活の一面を伺い知ることが出来る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000528"},{"id":"00000531","register_sub_id":"101","register_pk":"101521","name":"佐野家住宅調度蔵","kana":"さのけじゅうたくちょうどぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74577966,"lng":137.00834703,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造２階建，瓦葺，建築面積32㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0022","desc":"１，２番の蔵の南にあり，敷地背後へ通じる通路を挟んで建つ二階建の中規模の土蔵で，北側壁の２ヶ所に通路の前後を閉じる防火扉が付属する。正面の開口部は防火扉とし，正面に付加された庇も塗り込めた構造とする。南側の味噌蔵とは一体的な造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000531"},{"id":"00000530","register_sub_id":"101","register_pk":"101520","name":"佐野家住宅２番の蔵","kana":"さのけじゅうたくにばんのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74581521,"lng":137.00831776,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造２階建，瓦葺，建築面積20㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0021","desc":"１番の蔵の南に並び建つほぼ同規模，同型式の土蔵で，平入の正面に防火扉付きの出入口を設け，２階には小さな防火窓を開く。１番の蔵との間の隙間は，１，２階とも正面を壁で閉塞して一体的な造作となる。正面全体に庇を設け，建具を入れて蔵前とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000530"},{"id":"00000533","register_sub_id":"101","register_pk":"132560","name":"佐野家住宅防火壁","kana":"さのけじゅうたくぼうかへき","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.7458654,"lng":137.00842022,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造，長さ25m，高さ5.6m","structure_material":"煉瓦造","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0024","desc":"敷地の南側を区切る高さ５．６ｍ，延長２５ｍの巨大な防火壁。北側の防火壁が主屋の北側面と一体的な構成になるのに対し，独立して建つ。正面の親柱や壁上部の屋根も一体的に煉瓦で造作する。防火対策に腐心した居宅の好例としても知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000533"},{"id":"00000532","register_sub_id":"101","register_pk":"101522","name":"佐野家住宅味噌蔵","kana":"さのけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市御馬出町68","lat":36.74575143,"lng":137.0083669,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造２階建，瓦葺，建築面積49㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"16 － 0023","desc":"敷地背後の南端に建つ木造２階建の中規模の土蔵で，南側面に敷地の南側を区切る巨大な防火壁が接続する。４棟の蔵のうち最も大きく，南側は敷地の形状に沿って変則的な平面となる。正面北寄りに開口部を開くが，防火戸を引き戸とする点は特異である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000532"},{"id":"00000201","register_sub_id":"101","register_pk":"101191","name":"澤田家住宅主屋","kana":"さわだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県高岡市二塚10","lat":36.71613486,"lng":137.00609939,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建，瓦葺，建築面積220㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0011","desc":"建物の外観は洋風で、玄関ポーチや正面の破風の意匠が特徴的。平面は接客部が洋間になるほか座敷等は和風でまとめる住宅である。井波町から昭和２６年に移築したもので、ドーム屋根をもった２階建て塔屋のある洋風建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000201"},{"id":"00010763","register_sub_id":"101","register_pk":"201598","name":"じょうはな庵（旧中谷家住宅）主屋","kana":"じょうはないおり（きゅうなかたにけじゅうたく)しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市城端字大工町644-1他","lat":36.514034,"lng":136.902349,"geo_status":"db","era":"明治38頃／昭和25頃改修・平成13移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"16 ‐ 0109","desc":"城端別院善徳寺の門前町で通りに面する。間口三間半で右手に土間を通し、左手に八畳三室を並べる。二階は土間の一部を上方吹抜けとする他は居室を配する。登りせがいの軒や厚板葺の庇、二階正面の袖壁など当地の町家の特徴をよく示し、門前の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010763"},{"id":"00010764","register_sub_id":"101","register_pk":"201599","name":"じょうはな庵（旧中谷家住宅）土蔵","kana":"じょうはないおり（きゅうなかたにけじゅうたく)どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市城端字大工町647-11","lat":36.513953,"lng":136.902477,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"16 ‐ 0110","desc":"敷地南東隅に南北棟で建つ。桁行四・五メートル梁間四・二メートル、土蔵造二階建、切妻造、置屋根式の桟瓦葺である。外壁漆喰塗で、西面南寄りに開く戸口と、二階東面に穿つ小窓に鳥居形の額縁を表す。小屋は登梁形式とする。門前町の小路に趣を添える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010764"},{"id":"00011668","register_sub_id":"101","register_pk":"210684","name":"菅田家住宅衣装蔵","kana":"すがたけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市瀬羽町1854-1","lat":36.762721,"lng":137.335408,"geo_status":"db","era":"安政2年（1855）／平成27年改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0124","desc":"切妻造平入の二階建土蔵で、背面側の別の蔵と一体として覆屋の屋根がかけられている。外壁は白漆喰塗で、土戸の内側と外壁腰上部を黒漆喰とする。正面一階左には扉口を開き、その右、及び二階二所に大きな鳥居枠を付す窓を設けるなど、意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011668"},{"id":"00011667","register_sub_id":"101","register_pk":"210683","name":"菅田家住宅主屋","kana":"すがたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1855","lat":36.762808,"lng":137.335165,"geo_status":"db","era":"明治前期／平成22年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造3階建、瓦葺、建築面積192㎡","structure_material":"木造3階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0123","desc":"旧北陸街道に北面する町家。木造三階建、切妻造桟瓦葺で、右勝手に土間を通し、オイをワクノウチとする。背面西寄りには台所を突出させる。二階は街路側を物置とし、その背後に諸室を配するなど当地の標準的な構成を取る。地域の街路景観を形成する町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011667"},{"id":"00000198","register_sub_id":"101","register_pk":"101188","name":"棚田家住宅衣装蔵","kana":"たなだけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市伏木錦町14-26","lat":36.79330266,"lng":137.05932193,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積47㎡","structure_material":"土蔵造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0008","desc":"主屋の背面にあって道具蔵と並んで建ち屋敷構えを構成する。主屋から縁続きの広縁を張って蔵前とする。漆喰仕上げの中規模の土蔵で、切妻造、桟瓦葺になる。弓状に反らした形の扉構えの楣、腰下の黒漆喰仕上げ等の各部の技法にみるべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000198"},{"id":"00000197","register_sub_id":"101","register_pk":"101187","name":"棚田家住宅主屋","kana":"たなだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市伏木錦町14-26","lat":36.79323124,"lng":137.05943776,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建，瓦葺，建築面積408㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0007","desc":"７間×９間、茶室附属の木造２階建の商家で、小屋裏の隠し物置、２階の隠れ通路、廻船問屋としての広い土間など、平面に特徴がある。主柱が秋田杉の四方柾であるなど、部材の質も高く、北前船で栄えた時代の高岡の町並みを今に伝えて広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000197"},{"id":"00000199","register_sub_id":"101","register_pk":"101189","name":"棚田家住宅道具蔵","kana":"たなだけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市伏木錦町14-26","lat":36.7933683,"lng":137.05946575,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積79㎡","structure_material":"土蔵造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0009","desc":"屋敷地の北西角に位置し衣裳蔵と並び建つ屋敷構えを構成する要素となる大型の土蔵。衣裳蔵と同じ切妻造、桟瓦葺の土蔵で、正面に板敷及び畳の間をおいて蔵前とする。扉口の構えは衣裳蔵と同様であるが、扉口の位置は正面左寄りで防火戸がない点に違いがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000199"},{"id":"00000200","register_sub_id":"101","register_pk":"101190","name":"棚田家住宅味噌蔵","kana":"たなだけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市伏木錦町14-26","lat":36.79327564,"lng":137.05959219,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積20㎡","structure_material":"土蔵造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0010","desc":"屋敷地の東北に位置する小規模な土蔵造の蔵。東面は木造２階建の同規模の建物が棟続きとなり、南面に庇を付加して小部屋を造るなど改造はあるが、内部はよく保存されている。棚田家の内向きの生活を知る上で貴重な蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000200"},{"id":"00000403","register_sub_id":"101","register_pk":"101393","name":"谷村家住宅主屋","kana":"たにむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市伏木中央町1-6","lat":36.79688679,"lng":137.05918234,"geo_status":"db","era":"明治1","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建，瓦葺，建築面積86㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"16 － 0018","desc":"洋風建築が混在する伏木の町並みのなかにあって，伝統的な様式を保つ基準的な町家。正面２階部分は，貫みせの真壁及び細格子窓を開き，両端に袖壁を置く。庇下には霧避けを設ける。良質の材を用いた内部造作の質も高い。棟梁は地元の針山分吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000403"},{"id":"00004228","register_sub_id":"101","register_pk":"105218","name":"冨田家住宅","kana":"とみたけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県南砺市安居188-1","lat":36.60062425,"lng":136.88743505,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積365㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"16 － 0072","desc":"入母屋造，平入の木造２階建で，４周に下屋を廻し，屋根は総桟瓦葺である。伝統的な形式を基調とするが，全体に良材を用い，質の高い大工技術が隅々まで発揮されている。透き漆塗を施した木部，ガラスを多用した建具などにも，近代の和風意匠が表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004228"},{"id":"00012893","register_sub_id":"101","register_pk":"368089","name":"冨田家住宅北土蔵","kana":"とみたけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県南砺市安居188","lat":36.60082222,"lng":136.88696667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 150","desc":"主屋背面の石垣上に南土蔵と並んで建つ。南北棟の切妻造、置屋根式桟瓦葺、二階建で、東面に南土蔵と一連の吹放し下屋を通す。外壁漆喰塗で、北面に設けた上下階一体の掛子塗戸付窓枠の階境に波に亀の鏝絵を飾る。路地に面した敷地西北隅の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012893"},{"id":"00012894","register_sub_id":"101","register_pk":"368090","name":"冨田家住宅長屋門","kana":"とみたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県南砺市安居188","lat":36.60054167,"lng":136.88730278,"geo_status":"db","era":"江戸後期／江戸末期・昭和前期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 151","desc":"主屋正面に東面して建つ。切妻造桟瓦葺で、北を門口、南を真壁漆喰塗の物置とする。門口は間口三・二メートルで本柱を立てて板扉を備え、南に袖壁、北に潜戸を設け、冠木上の繰形付の出梁で軒桁を受ける。旧家の屋敷構えに厳かな趣を添える表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012894"},{"id":"00012891","register_sub_id":"101","register_pk":"368087","name":"冨田家住宅味噌蔵","kana":"とみたけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市安居188","lat":36.60079167,"lng":136.88707778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 148","desc":"主屋の北側に南面して建つ。土蔵造平屋建、東西棟の切妻造、置屋根式桟瓦葺で、戸口前に板敷の下屋を設け、主屋に接続する。外壁漆喰塗で、水切下に簓子下見板を張る。内部は東半を板敷、西半を土間とする。主屋と並び建ち、屋敷中心部の構えを引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012891"},{"id":"00012892","register_sub_id":"101","register_pk":"368088","name":"冨田家住宅南土蔵","kana":"とみたけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市安居188","lat":36.60076667,"lng":136.88693333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 149","desc":"主屋背面の石垣上に北土蔵と並んで建つ。南北棟の切妻造、置屋根式桟瓦葺、二階建で、東面に北土蔵と一連の吹放し下屋を通す。外壁漆喰塗で、東面の戸口に掛子塗戸を備え、他三面は水切下に簓子下見板を張る。北土蔵とともに背面の屋敷構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012892"},{"id":"00000344","register_sub_id":"101","register_pk":"101334","name":"富山市陶芸館","kana":"とやましとうげいかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県富山市安養坊50","lat":36.70948394,"lng":137.18994502,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積323㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"16 － 0014","desc":"「あずまだち」と呼ばれる切妻造の大型農家。元市内大塚に建てられたが，数回の移築を経て昭和５６年に民俗民芸村の陶芸館として再生された。壮大な破風と数多くの貫や束によって直線的に構成される妻壁の意匠は独特なもので，富山の豪農の居宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000344"},{"id":"00011671","register_sub_id":"101","register_pk":"210687","name":"滑川館道具蔵","kana":"なめりかわかんどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市神家町288-1","lat":36.764206,"lng":137.338145,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0127","desc":"滑川旧市街地の中心部に位置し、本館東面背面側に戸前を接して建つ。本館と同時期に建てられた土蔵造二階建、切妻造桟瓦葺で、白漆喰塗で黒塗の腰竪板を高く張る背面側を街路側に見せる。屋敷構を構成する土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011671"},{"id":"00011670","register_sub_id":"101","register_pk":"210686","name":"滑川館本館","kana":"なめりかわかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市神家町288-1","lat":36.764159,"lng":137.338012,"geo_status":"db","era":"明治20年／明治後期改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0128","desc":"木造二階建、切妻造桟瓦葺で、向かって左に土間玄関を設け、その奥はワクノウチとする。一階は二列八室、二階は吹抜けを囲むように客室四室を配す。地域の標準的な平面構成の住宅から改造されたもので、正面の瀟洒な格子戸などが、地域の景観を形作っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011670"},{"id":"00000402","register_sub_id":"101","register_pk":"101392","name":"能松家住宅主屋","kana":"のうまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市吉久2-3-2","lat":36.78008175,"lng":137.05654547,"geo_status":"db","era":"明治末期頃","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期頃","structure":"木造2階建，瓦葺，建築面積101㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"16 － 0017","desc":"回船で栄えた吉久の町並のほぼ中央部に位置する町家で，元米商を営んだ。間口４間半に比べ奥行７間半と長く，玄関及び７室が２列に整然と配される。玄関奥のオイでは，この地方独特の透き漆塗りの梁組を見せる。吉久の町家の好例であり，保存状況も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000402"}];
